const s={"es-first-u01.title":"Животные","es-first-u01.tip":"Смотрите на картинки, слушайте и повторяйте вместе. Читать пока не нужно.","es-first-u01.w.0":"кошка","es-first-u01.w.1":"собака","es-first-u01.w.2":"рыба","es-first-u01.w.3":"птица","es-first-u01.w.4":"корова","es-first-u01.w.5":"свинья","es-first-u02.title":"Еда","es-first-u02.tip":"Смотрите на картинки, слушайте и повторяйте вместе. Читать пока не нужно.","es-first-u02.w.0":"яблоко","es-first-u02.w.1":"банан","es-first-u02.w.2":"молоко","es-first-u02.w.3":"хлеб","es-first-u02.w.4":"яйцо","es-first-u02.w.5":"торт","es-first-u03.title":"Игрушки","es-first-u03.tip":"Смотрите на картинки, слушайте и повторяйте вместе. Читать пока не нужно.","es-first-u03.w.0":"мяч","es-first-u03.w.1":"машина","es-first-u03.w.2":"мишка","es-first-u03.w.3":"воздушный змей","es-first-u03.w.4":"поезд","es-first-u03.w.5":"лодка","es-first-u04.title":"Тело","es-first-u04.tip":"Смотрите на картинки, слушайте и повторяйте вместе. Читать пока не нужно.","es-first-u04.w.0":"глаз","es-first-u04.w.1":"ухо","es-first-u04.w.2":"нос","es-first-u04.w.3":"рот","es-first-u04.w.4":"рука","es-first-u04.w.5":"нога","es-first-u05.title":"Цвета","es-first-u05.tip":"Смотрите на картинки, слушайте и повторяйте вместе. Читать пока не нужно.","es-first-u05.w.0":"красный","es-first-u05.w.1":"синий","es-first-u05.w.2":"жёлтый","es-first-u05.w.3":"зелёный","es-first-u05.w.4":"чёрный","es-first-u05.w.5":"белый","es-first-u06.title":"Семья","es-first-u06.tip":"Смотрите на картинки, слушайте и повторяйте вместе. Читать пока не нужно.","es-first-u06.w.0":"мама","es-first-u06.w.1":"папа","es-first-u06.w.2":"малыш","es-first-u06.w.3":"мальчик","es-first-u06.w.4":"девочка","es-first-u06.w.5":"бабушка","es-first-u07.title":"Дома","es-first-u07.tip":"Смотрите на картинки, слушайте и повторяйте вместе. Читать пока не нужно.","es-first-u07.w.0":"кровать","es-first-u07.w.1":"стул","es-first-u07.w.2":"дверь","es-first-u07.w.3":"чашка","es-first-u07.w.4":"книга","es-first-u07.w.5":"часы","es-first-u08.title":"На улице","es-first-u08.tip":"Смотрите на картинки, слушайте и повторяйте вместе. Читать пока не нужно.","es-first-u08.w.0":"солнце","es-first-u08.w.1":"луна","es-first-u08.w.2":"звезда","es-first-u08.w.3":"дерево","es-first-u08.w.4":"цветок","es-first-u08.w.5":"дождь"},e={"es-kinder-u01.title":"Буквы A, B, C","es-kinder-u01.tip":"Повторяй названия испанских букв, как песенку: A — «а», B — «бэ», C — «сэ».","es-kinder-u01.w.0":"дерево","es-kinder-u01.w.1":"пчела","es-kinder-u01.w.2":"вода","es-kinder-u01.w.3":"малыш","es-kinder-u01.w.4":"кораблик","es-kinder-u01.w.5":"банан","es-kinder-u01.w.6":"дом","es-kinder-u01.w.7":"машина","es-kinder-u01.s.0":"A как в árbol (дерево).","es-kinder-u01.s.1":"B как в bebé (малыш).","es-kinder-u01.s.2":"C как в casa (дом).","es-kinder-u02.title":"Буквы D, E, F","es-kinder-u02.tip":"E читается как «э». Поищите вместе дома вещи, которые по-испански начинаются на D, E, F.","es-kinder-u02.w.0":"палец","es-kinder-u02.w.1":"кубик (игральный)","es-kinder-u02.w.2":"дельфин","es-kinder-u02.w.3":"слон","es-kinder-u02.w.4":"звезда","es-kinder-u02.w.5":"цветок","es-kinder-u02.w.6":"клубника","es-kinder-u02.w.7":"фото","es-kinder-u02.s.0":"D как в dado (кубик).","es-kinder-u02.s.1":"E как в elefante (слон).","es-kinder-u02.s.2":"F как в flor (цветок).","es-kinder-u03.title":"Буквы G, H, I","es-kinder-u03.tip":"Испанская H не произносится: huevo читается «уэво».","es-kinder-u03.w.0":"кот","es-kinder-u03.w.1":"воздушный шарик","es-kinder-u03.w.2":"курица","es-kinder-u03.w.3":"мороженое","es-kinder-u03.w.4":"яйцо","es-kinder-u03.w.5":"листок","es-kinder-u03.w.6":"остров","es-kinder-u03.w.7":"магнит","es-kinder-u03.s.0":"G как в gato (кот).","es-kinder-u03.s.1":"H как в huevo (яйцо).","es-kinder-u03.s.2":"I как в isla (остров).","es-kinder-u04.title":"Буквы J, K, L","es-kinder-u04.tip":"J — это звук «х» из горла: jirafa звучит как «хирафа».","es-kinder-u04.w.0":"жираф","es-kinder-u04.w.1":"сок","es-kinder-u04.w.2":"мыло","es-kinder-u04.w.3":"коала","es-kinder-u04.w.4":"киви","es-kinder-u04.w.5":"луна","es-kinder-u04.w.6":"лев","es-kinder-u04.w.7":"книга","es-kinder-u04.s.0":"J как в jirafa (жираф).","es-kinder-u04.s.1":"K как в koala (коала).","es-kinder-u04.s.2":"L как в luna (луна).","es-kinder-u05.title":"Буквы M, N, Ñ","es-kinder-u05.tip":"Ñ — буква, которая есть только в испанском. Звучит как «нь»: niño — это «ниньо»!","es-kinder-u05.w.0":"рука","es-kinder-u05.w.1":"яблоко","es-kinder-u05.w.2":"обезьяна","es-kinder-u05.w.3":"облако","es-kinder-u05.w.4":"нос","es-kinder-u05.w.5":"снег","es-kinder-u05.w.6":"мальчик","es-kinder-u05.w.7":"гну (антилопа)","es-kinder-u05.s.0":"M как в mano (рука).","es-kinder-u05.s.1":"N как в nube (облако).","es-kinder-u05.s.2":"Ñ как в ñu (гну).","es-kinder-u06.title":"Буквы O, P, Q","es-kinder-u06.tip":"После Q всегда стоит u, а читается как «к»: queso — это «кэсо».","es-kinder-u06.w.0":"медведь","es-kinder-u06.w.1":"глаз","es-kinder-u06.w.2":"овца","es-kinder-u06.w.3":"хлеб","es-kinder-u06.w.4":"утка","es-kinder-u06.w.5":"мяч","es-kinder-u06.w.6":"рыба","es-kinder-u06.w.7":"сыр","es-kinder-u06.s.0":"O как в oso (медведь).","es-kinder-u06.s.1":"P как в pan (хлеб).","es-kinder-u06.s.2":"Q как в queso (сыр).","es-kinder-u07.title":"Буквы R, S, T","es-kinder-u07.tip":"R произносится с дрожанием языка: «ррр». Если трудно, пока можно говорить обычное «р».","es-kinder-u07.w.0":"мышка","es-kinder-u07.w.1":"лягушка","es-kinder-u07.w.2":"солнце","es-kinder-u07.w.3":"суп","es-kinder-u07.w.4":"стул","es-kinder-u07.w.5":"поезд","es-kinder-u07.w.6":"помидор","es-kinder-u07.w.7":"черепаха","es-kinder-u07.s.0":"R как в rana (лягушка).","es-kinder-u07.s.1":"S как в sol (солнце).","es-kinder-u07.s.2":"T как в tren (поезд).","es-kinder-u08.title":"Буквы от U до Z","es-kinder-u08.tip":"V читается точно так же, как B — «б». Z звучит как мягкое «с». Теперь ты знаешь все буквы!","es-kinder-u08.w.0":"виноград","es-kinder-u08.w.1":"один","es-kinder-u08.w.2":"корова","es-kinder-u08.w.3":"стакан","es-kinder-u08.w.4":"йо-йо","es-kinder-u08.w.5":"яхта","es-kinder-u08.w.6":"ботинок","es-kinder-u08.w.7":"морковка","es-kinder-u08.s.0":"U как в uva (виноград).","es-kinder-u08.s.1":"V как в vaca (корова).","es-kinder-u08.s.2":"Z как в zapato (ботинок)."},g={"es-g12-u01.title":"Приветствия","es-g12-u01.tip":"В испанском восклицательный и вопросительный знаки ставят ещё и в начале предложения, вверх ногами (¡ ¿). Правда, интересно?","es-g12-u01.w.0":"привет","es-g12-u01.w.1":"пока","es-g12-u01.w.2":"спасибо","es-g12-u01.w.3":"пожалуйста","es-g12-u01.w.4":"да","es-g12-u01.w.5":"нет","es-g12-u01.w.6":"друг","es-g12-u01.w.7":"доброе утро","es-g12-u01.w.8":"спокойной ночи","es-g12-u01.s.0":"Привет, друг!","es-g12-u01.s.1":"Доброе утро, мама.","es-g12-u01.s.2":"Спасибо, пожалуйста.","es-g12-u01.s.3":"Да, спасибо.","es-g12-u01.s.4":"Нет, спасибо.","es-g12-u01.s.5":"Спокойной ночи, пока.","es-g12-u02.title":"Числа от 1 до 10","es-g12-u02.tip":"Разгибай пальцы по одному и считай от uno до diez.","es-g12-u02.w.0":"один","es-g12-u02.w.1":"два","es-g12-u02.w.2":"три","es-g12-u02.w.3":"четыре","es-g12-u02.w.4":"пять","es-g12-u02.w.5":"шесть","es-g12-u02.w.6":"семь","es-g12-u02.w.7":"восемь","es-g12-u02.w.8":"девять","es-g12-u02.w.9":"десять","es-g12-u02.s.0":"Один, два, три.","es-g12-u02.s.1":"Мне пять лет.","es-g12-u02.s.2":"Четыре плюс четыре — восемь.","es-g12-u02.s.3":"У меня две руки.","es-g12-u02.s.4":"Десять пальцев.","es-g12-u02.s.5":"Шесть, семь, восемь, девять, десять.","es-g12-u03.title":"Цвета","es-g12-u03.tip":'Название цвета стоит после слова, которое оно описывает: "manzana roja" (красное яблоко). После слов женского рода -o меняется на -a.',"es-g12-u03.w.0":"красный","es-g12-u03.w.1":"синий","es-g12-u03.w.2":"жёлтый","es-g12-u03.w.3":"зелёный","es-g12-u03.w.4":"белый","es-g12-u03.w.5":"чёрный","es-g12-u03.w.6":"розовый","es-g12-u03.w.7":"оранжевый","es-g12-u03.w.8":"фиолетовый","es-g12-u03.s.0":"Солнце жёлтое.","es-g12-u03.s.1":"Яблоко красное.","es-g12-u03.s.2":"Море синее.","es-g12-u03.s.3":"Мне нравится зелёный.","es-g12-u03.s.4":"Мой кот чёрный.","es-g12-u03.s.5":"Цветок розовый.","es-g12-u04.title":"Семья","es-g12-u04.tip":"В mamá и papá ударение падает на конец: «мамА», «папА». Значок ударения (´) показывает, где нажать голосом.","es-g12-u04.w.0":"мама","es-g12-u04.w.1":"папа","es-g12-u04.w.2":"брат","es-g12-u04.w.3":"сестра","es-g12-u04.w.4":"бабушка","es-g12-u04.w.5":"дедушка","es-g12-u04.w.6":"малыш","es-g12-u04.w.7":"семья","es-g12-u04.w.8":"собака","es-g12-u04.s.0":"Это моя мама.","es-g12-u04.s.1":"Мой папа высокий.","es-g12-u04.s.2":"У меня есть сестра.","es-g12-u04.s.3":"Моя бабушка добрая.","es-g12-u04.s.4":"Малыш спит.","es-g12-u04.s.5":"Моя семья большая.","es-g12-u05.title":"Животные","es-g12-u05.tip":"Перед названием животного ставь el или la: el gato, la vaca.","es-g12-u05.w.0":"кот","es-g12-u05.w.1":"птица","es-g12-u05.w.2":"рыба","es-g12-u05.w.3":"лошадь","es-g12-u05.w.4":"корова","es-g12-u05.w.5":"свинья","es-g12-u05.w.6":"кролик","es-g12-u05.w.7":"медведь","es-g12-u05.w.8":"лев","es-g12-u05.s.0":"Кот маленький.","es-g12-u05.s.1":"Лев большой.","es-g12-u05.s.2":"Корова ест траву.","es-g12-u05.s.3":"Птица поёт.","es-g12-u05.s.4":"Мне нравится кролик.","es-g12-u05.s.5":"Лошадь бежит быстро.","es-g12-u06.title":"Фрукты","es-g12-u06.tip":'"Me gusta" значит «мне нравится». Скажи так про свой любимый фрукт.',"es-g12-u06.w.0":"яблоко","es-g12-u06.w.1":"банан","es-g12-u06.w.2":"клубника","es-g12-u06.w.3":"виноград","es-g12-u06.w.4":"груша","es-g12-u06.w.5":"арбуз","es-g12-u06.w.6":"лимон","es-g12-u06.w.7":"персик","es-g12-u06.w.8":"вишня","es-g12-u06.s.0":"Мне нравится клубника.","es-g12-u06.s.1":"Арбуз большой.","es-g12-u06.s.2":"Я хочу яблоко.","es-g12-u06.s.3":"Лимон жёлтый.","es-g12-u06.s.4":"Виноград сладкий.","es-g12-u06.s.5":"Один банан, пожалуйста.","es-g12-u07.title":"Еда","es-g12-u07.tip":"como значит «я ем», bebo — «я пью». Попробуй сказать это за столом.","es-g12-u07.w.0":"хлеб","es-g12-u07.w.1":"рис","es-g12-u07.w.2":"молоко","es-g12-u07.w.3":"вода","es-g12-u07.w.4":"сыр","es-g12-u07.w.5":"яйцо","es-g12-u07.w.6":"суп","es-g12-u07.w.7":"курица","es-g12-u07.w.8":"пицца","es-g12-u07.s.0":"Я хочу хлеб с сыром.","es-g12-u07.s.1":"Я пью молоко.","es-g12-u07.s.2":"Суп горячий.","es-g12-u07.s.3":"Я ем рис с курицей.","es-g12-u07.s.4":"Воды, пожалуйста.","es-g12-u07.s.5":"Мне нравится пицца.","es-g12-u08.title":"Тело","es-g12-u08.tip":'"Me duele" значит «у меня болит». Добавь, что болит: Me duele la mano.',"es-g12-u08.w.0":"голова","es-g12-u08.w.1":"глаз","es-g12-u08.w.2":"нос","es-g12-u08.w.3":"рот","es-g12-u08.w.4":"ухо","es-g12-u08.w.5":"рука","es-g12-u08.w.6":"нога (ступня)","es-g12-u08.w.7":"волосы","es-g12-u08.w.8":"зуб","es-g12-u08.s.0":"У меня два глаза.","es-g12-u08.s.1":"Мои волосы чёрные.","es-g12-u08.s.2":"Дотронься до носа.","es-g12-u08.s.3":"У меня болит голова.","es-g12-u08.s.4":"Я мою руки.","es-g12-u08.s.5":"Открой рот.","es-g12-u09.title":"Школа","es-g12-u09.tip":'"Voy a" значит «я иду в». Voy a la escuela, voy a casa.',"es-g12-u09.w.0":"школа","es-g12-u09.w.1":"книга","es-g12-u09.w.2":"карандаш","es-g12-u09.w.3":"рюкзак","es-g12-u09.w.4":"парта","es-g12-u09.w.5":"учитель","es-g12-u09.w.6":"бумага","es-g12-u09.w.7":"ножницы","es-g12-u09.w.8":"доска","es-g12-u09.s.0":"Я иду в школу.","es-g12-u09.s.1":"У меня есть карандаш.","es-g12-u09.s.2":"Книга на парте.","es-g12-u09.s.3":"Мой рюкзак синий.","es-g12-u09.s.4":"Учитель добрый.","es-g12-u09.s.5":"Дай мне бумагу.","es-g12-u10.title":"Мой дом","es-g12-u10.tip":'"está en" значит «находится в». Расскажи, где лежат вещи.',"es-g12-u10.w.0":"дом","es-g12-u10.w.1":"дверь","es-g12-u10.w.2":"окно","es-g12-u10.w.3":"кровать","es-g12-u10.w.4":"кухня","es-g12-u10.w.5":"ванная","es-g12-u10.w.6":"диван","es-g12-u10.w.7":"лампа","es-g12-u10.w.8":"сад","es-g12-u10.s.0":"Мой дом маленький.","es-g12-u10.s.1":"Открой дверь.","es-g12-u10.s.2":"Я сплю в своей кровати.","es-g12-u10.s.3":"Мама на кухне.","es-g12-u10.s.4":"Кот на диване.","es-g12-u10.s.5":"В саду есть цветы.","es-g12-u11.title":"Одежда","es-g12-u11.tip":'"Me pongo" значит «я надеваю». Говори это утром, когда одеваешься.',"es-g12-u11.w.0":"футболка","es-g12-u11.w.1":"брюки","es-g12-u11.w.2":"ботинки","es-g12-u11.w.3":"шапка","es-g12-u11.w.4":"платье","es-g12-u11.w.5":"пальто","es-g12-u11.w.6":"носки","es-g12-u11.w.7":"шарф","es-g12-u11.w.8":"перчатки","es-g12-u11.s.0":"Я надеваю футболку.","es-g12-u11.s.1":"Мои ботинки красные.","es-g12-u11.s.2":"Холодно, надень пальто.","es-g12-u11.s.3":"Мне нравится это платье.","es-g12-u11.s.4":"Где моя шапка?","es-g12-u11.s.5":"Носки синие.","es-g12-u12.title":"Погода","es-g12-u12.tip":"О погоде говорят с hace: Hace sol (солнечно), Hace frío (холодно), Hace calor (жарко).","es-g12-u12.w.0":"солнце","es-g12-u12.w.1":"дождь","es-g12-u12.w.2":"снег","es-g12-u12.w.3":"ветер","es-g12-u12.w.4":"облако","es-g12-u12.w.5":"жара","es-g12-u12.w.6":"холод","es-g12-u12.w.7":"зонт","es-g12-u12.w.8":"радуга","es-g12-u12.s.0":"Светит солнце.","es-g12-u12.s.1":"Сегодня холодно.","es-g12-u12.s.2":"Идёт сильный дождь.","es-g12-u12.s.3":"В горах лежит снег.","es-g12-u12.s.4":"Очень жарко.","es-g12-u12.s.5":"Смотри, радуга.","es-g12-u13.title":"Дни недели и время дня","es-g12-u13.tip":"Дни недели в испанском пишутся с маленькой буквы. mañana значит и «завтра», и «утро».","es-g12-u13.w.0":"понедельник","es-g12-u13.w.1":"вторник","es-g12-u13.w.2":"суббота","es-g12-u13.w.3":"воскресенье","es-g12-u13.w.4":"сегодня","es-g12-u13.w.5":"завтра","es-g12-u13.w.6":"ночь","es-g12-u13.w.7":"день (после обеда)","es-g12-u13.w.8":"неделя","es-g12-u13.s.0":"Сегодня понедельник.","es-g12-u13.s.1":"Завтра вторник.","es-g12-u13.s.2":"В субботу нет школы.","es-g12-u13.s.3":"Добрый день.","es-g12-u13.s.4":"Ночью я сплю.","es-g12-u13.s.5":"В воскресенье я играю с папой.","es-g12-u14.title":"Транспорт","es-g12-u14.tip":'"Voy en" значит «я еду на»: voy en tren, voy en coche.',"es-g12-u14.w.0":"машина","es-g12-u14.w.1":"автобус","es-g12-u14.w.2":"поезд","es-g12-u14.w.3":"велосипед","es-g12-u14.w.4":"самолёт","es-g12-u14.w.5":"корабль","es-g12-u14.w.6":"мотоцикл","es-g12-u14.w.7":"такси","es-g12-u14.w.8":"грузовик","es-g12-u14.s.0":"Я еду на автобусе.","es-g12-u14.s.1":"Поезд быстрый.","es-g12-u14.s.2":"У меня есть красный велосипед.","es-g12-u14.s.3":"Самолёт летит высоко.","es-g12-u14.s.4":"Корабль в море.","es-g12-u14.s.5":"У папы есть машина.","es-g12-u15.title":"Игрушки и игры","es-g12-u15.tip":'"Vamos a" значит «пойдём, давай». Скажи другу: Vamos al parque!',"es-g12-u15.w.0":"мяч","es-g12-u15.w.1":"кукла","es-g12-u15.w.2":"плюшевый мишка","es-g12-u15.w.3":"игрушечная машинка","es-g12-u15.w.4":"пазл","es-g12-u15.w.5":"воздушный змей","es-g12-u15.w.6":"воздушный шарик","es-g12-u15.w.7":"игра","es-g12-u15.w.8":"детская площадка","es-g12-u15.s.0":"Я играю с мячом.","es-g12-u15.s.1":"Моя кукла красивая.","es-g12-u15.s.2":"Пойдём на площадку.","es-g12-u15.s.3":"Шарик красный.","es-g12-u15.s.4":"Мне нравится эта игра.","es-g12-u15.s.5":"Воздушный змей летит.","es-g12-u16.title":"Природа","es-g12-u16.tip":'"Veo" значит «я вижу». Выйди на улицу и назови то, что видишь.',"es-g12-u16.w.0":"дерево","es-g12-u16.w.1":"цветок","es-g12-u16.w.2":"река","es-g12-u16.w.3":"гора","es-g12-u16.w.4":"море","es-g12-u16.w.5":"луна","es-g12-u16.w.6":"звезда","es-g12-u16.w.7":"камень","es-g12-u16.w.8":"трава","es-g12-u16.s.0":"Дерево высокое.","es-g12-u16.s.1":"Луна белая.","es-g12-u16.s.2":"Я вижу звезду.","es-g12-u16.s.3":"Река длинная.","es-g12-u16.s.4":"В горах есть цветы.","es-g12-u16.s.5":"Мне нравится море.","es-g12-u17.title":"Настроение","es-g12-u17.tip":"О настроении говорят с estoy: Estoy feliz. Если ты девочка, слова заканчиваются на -a: cansada, enfadada.","es-g12-u17.w.0":"счастливый","es-g12-u17.w.1":"грустный","es-g12-u17.w.2":"сердитый","es-g12-u17.w.3":"усталый","es-g12-u17.w.4":"испуганный","es-g12-u17.w.5":"довольный","es-g12-u17.w.6":"скучающий","es-g12-u17.w.7":"удивлённый","es-g12-u17.w.8":"больной","es-g12-u17.s.0":"Я счастлив.","es-g12-u17.s.1":"Тебе грустно?","es-g12-u17.s.2":"Я очень устал.","es-g12-u17.s.3":"Мой брат сердится.","es-g12-u17.s.4":"Я не боюсь.","es-g12-u17.s.5":"Я сегодня болею.","es-g12-u18.title":"Действия","es-g12-u18.tip":'Слова на -ar, -er, -ir — это действия. Их можно ставить сразу после "Me gusta".',"es-g12-u18.w.0":"бегать","es-g12-u18.w.1":"прыгать","es-g12-u18.w.2":"есть","es-g12-u18.w.3":"пить","es-g12-u18.w.4":"спать","es-g12-u18.w.5":"читать","es-g12-u18.w.6":"петь","es-g12-u18.w.7":"танцевать","es-g12-u18.w.8":"плавать","es-g12-u18.s.0":"Мне нравится бегать.","es-g12-u18.s.1":"Я хочу есть.","es-g12-u18.s.2":"Пойдём плавать.","es-g12-u18.s.3":"Она хорошо поёт.","es-g12-u18.s.4":"Я читаю книгу.","es-g12-u18.s.5":"Собака прыгает.","es-g12-u19.title":"Мой район","es-g12-u19.tip":'"Hay" значит «есть, имеется». Гуляя по району, говори: Hay una tienda, hay un parque.',"es-g12-u19.w.0":"улица","es-g12-u19.w.1":"магазин","es-g12-u19.w.2":"парк","es-g12-u19.w.3":"больница","es-g12-u19.w.4":"библиотека","es-g12-u19.w.5":"булочная","es-g12-u19.w.6":"рынок","es-g12-u19.w.7":"церковь","es-g12-u19.w.8":"светофор","es-g12-u19.s.0":"Я живу на этой улице.","es-g12-u19.s.1":"Я иду в магазин.","es-g12-u19.s.2":"Библиотека близко.","es-g12-u19.s.3":"Я покупаю хлеб в булочной.","es-g12-u19.s.4":"Светофор красный.","es-g12-u19.s.5":"Здесь есть парк.","es-g12-u20.title":"День рождения","es-g12-u20.tip":'"¡Feliz cumpleaños!" — это поздравление с днём рождения. Обязательно скажи так другу в его праздник.',"es-g12-u20.w.0":"день рождения","es-g12-u20.w.1":"подарок","es-g12-u20.w.2":"торт","es-g12-u20.w.3":"свечка","es-g12-u20.w.4":"праздник","es-g12-u20.w.5":"песня","es-g12-u20.w.6":"друзья","es-g12-u20.w.7":"праздничный колпак","es-g12-u20.w.8":"мороженое","es-g12-u20.s.0":"С днём рождения!","es-g12-u20.s.1":"Сегодня мой праздник.","es-g12-u20.s.2":"У меня есть подарок для тебя.","es-g12-u20.s.3":"Задуй свечки.","es-g12-u20.s.4":"Мы поём песню.","es-g12-u20.s.5":"Мои друзья едят торт."},u={"es-g34-u01.title":"Я — это я: рассказываем о себе","es-g34-u01.tip":'В испанском часто пропускают подлежащее. Просто "Soy Lucía" уже значит «Я Лусия».',"es-g34-u01.w.0":"ученик","es-g34-u01.w.1":"учительница","es-g34-u01.w.2":"врач","es-g34-u01.w.3":"повар","es-g34-u01.w.4":"приветливый","es-g34-u01.w.5":"высокий","es-g34-u01.w.6":"низкий (ростом)","es-g34-u01.w.7":"умный","es-g34-u01.w.8":"имя","es-g34-u01.w.9":"страна","es-g34-u01.s.0":"Я Лусия.","es-g34-u01.s.1":"Я из Перу.","es-g34-u01.s.2":"Ты мой друг.","es-g34-u01.s.3":"Он врач.","es-g34-u01.s.4":"Она очень умная.","es-g34-u01.s.5":"Мы ученики.","es-g34-u01.s.6":"Моя учительница приветливая.","es-g34-u01.s.7":"Как тебя зовут?","es-g34-u01.g.title":"Глагол ser: soy, eres, es","es-g34-u01.g.x.0":"«Быть» — это глагол ser. Он меняется в зависимости от того, о ком речь: yo soy, tú eres, él/ella es.","es-g34-u01.g.x.1":"Если нас много: nosotros somos, ellos son.","es-g34-u01.g.x.2":"Ser нужен, чтобы сказать имя, профессию, страну и характер. Soy estudiante. Es de México.","es-g34-u01.g.0":"Я ученик.","es-g34-u01.g.1":"Ты высокий.","es-g34-u01.g.2":"Она учительница.","es-g34-u01.g.3":"Мы друзья.","es-g34-u01.g.4":"Они из Испании.","es-g34-u01.g.5":"Ты мой друг.","es-g34-u01.g.5.task":'Перепиши так, чтобы предложение начиналось с "Tú"',"es-g34-u01.g.6":"Она умная.","es-g34-u01.g.6.task":'Перепиши так, чтобы предложение начиналось с "Ella"',"es-g34-u01.g.7":"Мы ученики.","es-g34-u01.g.7.task":'Перепиши так, чтобы предложение начиналось с "Nosotros"',"es-g34-u01.st.title":"Новый друг","es-g34-u01.st.l.0":"Привет! Я Лусия. Как тебя зовут?","es-g34-u01.st.l.1":"Я Матео. Я из Мексики.","es-g34-u01.st.l.2":"А я из Перу. Я ученица.","es-g34-u01.st.l.3":"Я тоже. Моя мама — врач.","es-g34-u01.st.l.4":"Здорово! А мой папа — повар.","es-g34-u01.st.l.5":"Ты очень приветливая, Лусия.","es-g34-u01.st.q.0":"Откуда Матео?","es-g34-u01.st.q.0.o.0":"Из Мексики","es-g34-u01.st.q.0.o.1":"Из Перу","es-g34-u01.st.q.0.o.2":"Из Испании","es-g34-u01.st.q.1":"Кем работает папа Лусии?","es-g34-u01.st.q.1.o.0":"Врачом","es-g34-u01.st.q.1.o.1":"Поваром","es-g34-u01.st.q.1.o.2":"Учителем","es-g34-u02.title":"Где ты? Как настроение?","es-g34-u02.tip":"Настроение — это estar! Estoy feliz, estoy cansado. Если ты девочка, слова заканчиваются на -a: contenta, nerviosa.","es-g34-u02.w.0":"здесь","es-g34-u02.w.1":"там","es-g34-u02.w.2":"близко","es-g34-u02.w.3":"далеко","es-g34-u02.w.4":"довольный","es-g34-u02.w.5":"взволнованный","es-g34-u02.w.6":"занятой","es-g34-u02.w.7":"готовый","es-g34-u02.w.8":"наверху (на)","es-g34-u02.w.9":"внизу (под)","es-g34-u02.s.0":"Я дома.","es-g34-u02.s.1":"Где ты?","es-g34-u02.s.2":"Книга на парте.","es-g34-u02.s.3":"Мама занята.","es-g34-u02.s.4":"Мы очень довольны.","es-g34-u02.s.5":"Школа близко.","es-g34-u02.s.6":"Я немного волнуюсь.","es-g34-u02.s.7":"Ты готов?","es-g34-u02.g.title":"Глагол estar: где и как","es-g34-u02.g.x.0":"Где кто-то находится и как себя чувствует сейчас — говорим с estar: estoy, estás, está, estamos, están.","es-g34-u02.g.x.1":"Estoy en casa. (Я дома) / Está contento. (Он доволен)","es-g34-u02.g.x.2":"ser — «какой он вообще», estar — «как и где он сейчас».","es-g34-u02.g.0":"Я в школе.","es-g34-u02.g.1":"Ты доволен?","es-g34-u02.g.2":"Кот под стулом.","es-g34-u02.g.3":"Мы готовы.","es-g34-u02.g.4":"Они далеко.","es-g34-u02.g.5":"Она волнуется.","es-g34-u02.g.5.task":'Перепиши так, чтобы предложение начиналось с "Ella"',"es-g34-u02.g.6":"Где ты?","es-g34-u02.g.6.task":'Преврати в вопрос с "¿Dónde…?"',"es-g34-u02.g.7":"Мы дома.","es-g34-u02.g.7.task":'Перепиши так, чтобы предложение начиналось с "Nosotros"',"es-g34-u03.title":"el и la: род слова","es-g34-u03.tip":'Запоминая новое слово, обязательно запоминай вместе с ним el/la. Не "mesa", а "la mesa"!',"es-g34-u03.w.0":"мальчик","es-g34-u03.w.1":"девочка","es-g34-u03.w.2":"парень","es-g34-u03.w.3":"девушка","es-g34-u03.w.4":"тетрадь","es-g34-u03.w.5":"окно","es-g34-u03.w.6":"деревня (посёлок)","es-g34-u03.w.7":"город","es-g34-u03.w.8":"рука","es-g34-u03.w.9":"задача (проблема)","es-g34-u03.s.0":"У мальчика есть тетрадь.","es-g34-u03.s.1":"Девочка открывает окно.","es-g34-u03.s.2":"Ребята играют в футбол.","es-g34-u03.s.3":"Девушки поют.","es-g34-u03.s.4":"Город очень большой.","es-g34-u03.s.5":"Деревня маленькая и красивая.","es-g34-u03.s.6":"На руке пять пальцев.","es-g34-u03.s.7":"Эта задача трудная.","es-g34-u03.g.title":"Артикли el / la / los / las","es-g34-u03.g.x.0":"Испанские существительные бывают мужского и женского рода. Обычно на -o — мужской (el niño), на -a — женский (la niña).","es-g34-u03.g.x.1":"Во множественном числе — los, las: los niños, las niñas.","es-g34-u03.g.x.2":"Есть исключения: la mano (женский), el problema (мужской). Учи слово вместе с артиклем.","es-g34-u03.g.0":"Мальчик ест хлеб.","es-g34-u03.g.1":"У девочки есть кот.","es-g34-u03.g.2":"Ребята в парке.","es-g34-u03.g.3":"Окна открыты.","es-g34-u03.g.3.task":"Поставь во множественное число","es-g34-u03.g.4":"Рука маленькая.","es-g34-u03.g.5":"Эта задача лёгкая.","es-g34-u03.g.6":"Дети играют.","es-g34-u03.g.6.task":"Поставь во множественное число","es-g34-u03.g.7":"Девушки поют.","es-g34-u03.g.7.task":"Поставь во множественное число","es-g34-u03.st.title":"В классе","es-g34-u03.st.l.0":"Доброе утро, ребята. Откройте тетради.","es-g34-u03.st.l.1":"Учительница, у меня нет тетради.","es-g34-u03.st.l.2":"Где твоя тетрадь, Диего?","es-g34-u03.st.l.3":"Дома, на столе.","es-g34-u03.st.l.4":"У меня две тетради. Возьми одну.","es-g34-u03.st.l.5":"Спасибо, Ана! Ты очень добрая.","es-g34-u03.st.q.0":"Где тетрадь Диего?","es-g34-u03.st.q.0.o.0":"В школе","es-g34-u03.st.q.0.o.1":"Дома на столе","es-g34-u03.st.q.0.o.2":"В рюкзаке","es-g34-u03.st.q.1":"Кто одалживает тетрадь?","es-g34-u03.st.q.1.o.0":"Учительница","es-g34-u03.st.q.1.o.1":"Диего","es-g34-u03.st.q.1.o.2":"Ана","es-g34-u04.title":"Красное яблоко, красные яблоки: прилагательные","es-g34-u04.tip":"Если существительное на -a, прилагательное тоже на -a; если существительных много, прилагательное тоже с -s. Они ходят парой.","es-g34-u04.w.0":"большой","es-g34-u04.w.1":"маленький","es-g34-u04.w.2":"красивый","es-g34-u04.w.3":"некрасивый","es-g34-u04.w.4":"новый","es-g34-u04.w.5":"старый","es-g34-u04.w.6":"быстрый","es-g34-u04.w.7":"медленный","es-g34-u04.w.8":"чистый","es-g34-u04.w.9":"грязный","es-g34-u04.s.0":"Яблоко красное.","es-g34-u04.s.1":"Яблоки красные.","es-g34-u04.s.2":"Новая машина быстрая.","es-g34-u04.s.3":"Мой дом маленький и красивый.","es-g34-u04.s.4":"Старые книги грязные.","es-g34-u04.s.5":"Черепаха медленная.","es-g34-u04.s.6":"Мои ботинки чистые.","es-g34-u04.s.7":"Большая собака некрасивая.","es-g34-u04.g.title":"Согласование прилагательных: -o/-a, -os/-as","es-g34-u04.g.x.0":"Прилагательное подстраивается под существительное: el niño alto, la niña alta.","es-g34-u04.g.x.1":"Во множественном числе добавляем -s: los niños altos, las niñas altas.","es-g34-u04.g.x.2":"Слова на -e, как grande, inteligente, одинаковы для мальчиков и девочек: el niño grande, la niña grande.","es-g34-u04.g.x.3":"Обычно прилагательное стоит после существительного: la casa bonita.","es-g34-u04.g.0":"Дом красивый.","es-g34-u04.g.1":"Машина новая.","es-g34-u04.g.2":"Собаки быстрые.","es-g34-u04.g.3":"Девочки умные.","es-g34-u04.g.4":"Черепаха медленная.","es-g34-u04.g.5":"Яблоки красные.","es-g34-u04.g.5.task":"Поставь во множественное число","es-g34-u04.g.6":"Рюкзак новый.","es-g34-u04.g.6.task":'Перепиши с "La mochila"',"es-g34-u04.g.7":"Коты маленькие.","es-g34-u04.g.7.task":"Поставь во множественное число","es-g34-u05.title":"Глаголы на -ar: hablo, hablas, habla","es-g34-u05.tip":"-o (я), -as (ты), -a (он/она), -amos (мы), -an (они). По одному окончанию видно, кто делает!","es-g34-u05.w.0":"говорить","es-g34-u05.w.1":"учиться","es-g34-u05.w.2":"слушать","es-g34-u05.w.3":"ходить пешком","es-g34-u05.w.4":"готовить (еду)","es-g34-u05.w.5":"рисовать","es-g34-u05.w.6":"работать","es-g34-u05.w.7":"плавать","es-g34-u05.w.8":"музыка","es-g34-u05.w.9":"бассейн","es-g34-u05.s.0":"Я говорю по-испански.","es-g34-u05.s.1":"Ты много учишься.","es-g34-u05.s.2":"Она слушает музыку.","es-g34-u05.s.3":"Мы идём пешком до парка.","es-g34-u05.s.4":"Мой папа готовит ужин.","es-g34-u05.s.5":"Дети рисуют животных.","es-g34-u05.s.6":"Мама работает по понедельникам.","es-g34-u05.s.7":"Мы плаваем в бассейне.","es-g34-u05.g.title":"Правильные глаголы на -ar в настоящем времени","es-g34-u05.g.x.0":"У глаголов на -ar убираем -ar и добавляем окончание для нужного лица: habl-o, habl-as, habl-a, habl-amos, habl-an.","es-g34-u05.g.x.1":"yo hablo (я говорю), tú hablas (ты), él/ella habla (он/она), nosotros hablamos (мы), ellos hablan (они).","es-g34-u05.g.x.2":"estudiar, caminar, cocinar меняются точно так же.","es-g34-u05.g.0":"Я разговариваю с бабушкой.","es-g34-u05.g.1":"Ты быстро ходишь.","es-g34-u05.g.2":"Она очень хорошо рисует.","es-g34-u05.g.3":"Мы плаваем каждую субботу.","es-g34-u05.g.4":"Они слушают учительницу.","es-g34-u05.g.5":"Она учит английский.","es-g34-u05.g.5.task":'Перепиши так, чтобы предложение начиналось с "Ella"',"es-g34-u05.g.6":"Мы работаем дома.","es-g34-u05.g.6.task":'Перепиши так, чтобы предложение начиналось с "Nosotros"',"es-g34-u05.g.7":"Ты готовишь ужин.","es-g34-u05.g.7.task":'Перепиши так, чтобы предложение начиналось с "Tú"',"es-g34-u06.title":"Глаголы на -er и -ir: como, vivo","es-g34-u06.tip":"-er и -ir почти одинаковые. Отличаются только с «мы»: comemos / vivimos.","es-g34-u06.w.0":"есть (кушать)","es-g34-u06.w.1":"пить","es-g34-u06.w.2":"читать","es-g34-u06.w.3":"учить (узнавать новое)","es-g34-u06.w.4":"бегать","es-g34-u06.w.5":"жить","es-g34-u06.w.6":"писать","es-g34-u06.w.7":"открывать","es-g34-u06.w.8":"письмо","es-g34-u06.w.9":"сказка (рассказ)","es-g34-u06.s.0":"Я ем рис.","es-g34-u06.s.1":"Ты пьёшь молоко.","es-g34-u06.s.2":"Она читает сказку.","es-g34-u06.s.3":"Мы учим испанский.","es-g34-u06.s.4":"Я живу в Лиме.","es-g34-u06.s.5":"Он пишет письмо.","es-g34-u06.s.6":"Дети быстро бегают.","es-g34-u06.s.7":"Мы открываем окно.","es-g34-u06.g.title":"Правильные глаголы на -er / -ir в настоящем времени","es-g34-u06.g.x.0":"Глаголы на -er: com-o, com-es, com-e, com-emos, com-en.","es-g34-u06.g.x.1":"Глаголы на -ir: viv-o, viv-es, viv-e, viv-imos, viv-en. Только «мы» отличается: -imos.","es-g34-u06.g.x.2":"Сравни с -ar: tú hablas / tú comes / tú vives. Запомни: a меняется на e.","es-g34-u06.g.0":"Я ем хлеб.","es-g34-u06.g.1":"Ты читаешь много книг.","es-g34-u06.g.2":"Она живёт в Мадриде.","es-g34-u06.g.3":"Мы живём здесь.","es-g34-u06.g.4":"Они пьют воду.","es-g34-u06.g.5":"Мы едим вместе.","es-g34-u06.g.5.task":'Перепиши с "Nosotros … juntos"',"es-g34-u06.g.6":"Она пишет письмо.","es-g34-u06.g.6.task":'Перепиши так, чтобы предложение начиналось с "Ella"',"es-g34-u06.g.7":"Ты открываешь дверь.","es-g34-u06.g.7.task":'Перепиши так, чтобы предложение начиналось с "Tú"',"es-g34-u07.title":"Мне нравится: gustar","es-g34-u07.tip":"gusta/gustan согласуется не с «я», а с тем, что нравится. Если нравится много всего — gustan!","es-g34-u07.w.0":"шоколад","es-g34-u07.w.1":"футбол","es-g34-u07.w.2":"фильм","es-g34-u07.w.3":"спорт","es-g34-u07.w.4":"овощи","es-g34-u07.w.5":"десерт","es-g34-u07.w.6":"домашнее задание","es-g34-u07.w.7":"любимый","es-g34-u07.w.8":"танцевать","es-g34-u07.w.9":"петь","es-g34-u07.s.0":"Мне нравится шоколад.","es-g34-u07.s.1":"Мне нравится спорт.","es-g34-u07.s.2":"Тебе нравится футбол?","es-g34-u07.s.3":"Мне не нравятся овощи.","es-g34-u07.s.4":"Матео любит танцевать.","es-g34-u07.s.5":"Мой любимый десерт — мороженое.","es-g34-u07.s.6":"Нам нравится смотреть фильмы.","es-g34-u07.s.7":"Мне не нравится домашнее задание.","es-g34-u07.g.title":"gustar: me gusta / me gustan","es-g34-u07.g.x.0":"«Мне нравится» — me gusta. Если нравится одна вещь — gusta, если несколько — gustan.","es-g34-u07.g.x.1":"Me gusta el helado. / Me gustan las fresas.","es-g34-u07.g.x.2":"Тебе — te gusta, ему/ей — le gusta, нам — nos gusta. Если называешь человека по имени: A Ana le gusta…","es-g34-u07.g.x.3":"Когда нравится действие, всегда gusta: Me gusta bailar.","es-g34-u07.g.0":"Мне нравится шоколад.","es-g34-u07.g.1":"Мне нравятся фильмы.","es-g34-u07.g.2":"Тебе нравится футбол?","es-g34-u07.g.3":"Лусия любит петь.","es-g34-u07.g.4":"Нам нравится музыка.","es-g34-u07.g.5":"Мне нравится спорт.","es-g34-u07.g.5.task":'Перепиши с "los deportes" (во множественном числе)',"es-g34-u07.g.6":"Мне не нравится домашнее задание.","es-g34-u07.g.6.task":"Сделай предложение отрицательным (no)","es-g34-u07.g.7":"Тебе нравятся овощи?","es-g34-u07.g.7.task":'Преврати в вопрос с "¿Te…?"',"es-g34-u07.st.title":"Время перекуса","es-g34-u07.st.l.0":"Уго, тебе нравится шоколад?","es-g34-u07.st.l.1":"Да! Очень нравится. А тебе?","es-g34-u07.st.l.2":"Мне нравится клубника. Это мой любимый десерт.","es-g34-u07.st.l.3":"А овощи тебе нравятся?","es-g34-u07.st.l.4":"Нет, не нравятся. Но суп я люблю.","es-g34-u07.st.l.5":"Моя мама любит варить суп. Пойдём ко мне домой!","es-g34-u07.st.q.0":"Какой десерт у Софии любимый?","es-g34-u07.st.q.0.o.0":"Шоколад","es-g34-u07.st.q.0.o.1":"Клубника","es-g34-u07.st.q.0.o.2":"Суп","es-g34-u07.st.q.1":"Что Софии не нравится?","es-g34-u07.st.q.1.o.0":"Суп","es-g34-u07.st.q.1.o.1":"Клубника","es-g34-u07.st.q.1.o.2":"Овощи","es-g34-u08.title":"Мой, твой: mi, tu, su","es-g34-u08.tip":'У tu (твой) нет ударения, а у tú (ты) есть. "tú tienes tu libro" — у тебя есть твоя книга.',"es-g34-u08.w.0":"игрушка","es-g34-u08.w.1":"велосипед","es-g34-u08.w.2":"домашний питомец","es-g34-u08.w.3":"сосед","es-g34-u08.w.4":"двоюродный брат","es-g34-u08.w.5":"дядя","es-g34-u08.w.6":"тётя","es-g34-u08.w.7":"комната","es-g34-u08.w.8":"телефон","es-g34-u08.w.9":"деньги","es-g34-u08.s.0":"Мой питомец — собака.","es-g34-u08.s.1":"Твой велосипед новый.","es-g34-u08.s.2":"Её комната большая.","es-g34-u08.s.3":"Наш дом близко.","es-g34-u08.s.4":"Мои двоюродные братья живут в Чили.","es-g34-u08.s.5":"Где твой телефон?","es-g34-u08.s.6":"У нашей тёти два кота.","es-g34-u08.s.7":"Его игрушки в коробке.","es-g34-u08.g.title":"Притяжательные mi / tu / su / nuestro","es-g34-u08.g.x.0":"мой = mi, твой = tu, его/её = su, наш = nuestro/nuestra.","es-g34-u08.g.x.1":"Если предметов много, добавляем -s: mis libros, tus zapatos, sus gatos.","es-g34-u08.g.x.2":"Только nuestro меняет род: nuestro perro, nuestra casa.","es-g34-u08.g.0":"Мой питомец — кот.","es-g34-u08.g.1":"Твои ботинки новые.","es-g34-u08.g.2":"Его двоюродный брат живёт в Мексике.","es-g34-u08.g.3":"Наш дом красивый.","es-g34-u08.g.4":"Наши соседи приветливые.","es-g34-u08.g.5":"Мои игрушки здесь.","es-g34-u08.g.5.task":"Поставь во множественное число","es-g34-u08.g.6":"Твой телефон новый.","es-g34-u08.g.6.task":'Перепиши с "Tu" (твой)',"es-g34-u08.g.7":"Её тётя живёт рядом.","es-g34-u08.g.7.task":'Перепиши с "Su" (её)',"es-g34-u09.title":"Что? Кто? Где?: задаём вопросы","es-g34-u09.tip":"В вопросе обязательно ставь перевёрнутый знак ¿ в начале. Когда читаешь, повышай голос в конце.","es-g34-u09.w.0":"что","es-g34-u09.w.1":"кто","es-g34-u09.w.2":"где","es-g34-u09.w.3":"когда","es-g34-u09.w.4":"как","es-g34-u09.w.5":"сколько","es-g34-u09.w.6":"почему","es-g34-u09.w.7":"ответ","es-g34-u09.w.8":"вопрос","es-g34-u09.w.9":"стоить","es-g34-u09.s.0":"Что это?","es-g34-u09.s.1":"Кто она?","es-g34-u09.s.2":"Где ты живёшь?","es-g34-u09.s.3":"Когда праздник?","es-g34-u09.s.4":"Как тебя зовут?","es-g34-u09.s.5":"Сколько стоит книга?","es-g34-u09.s.6":"Почему ты плачешь?","es-g34-u09.s.7":"У меня есть вопрос.","es-g34-u09.g.title":"Вопросительные слова: qué, quién, dónde, cuándo, cómo, cuánto","es-g34-u09.g.x.0":"У всех вопросительных слов есть знак ударения: qué (что), quién (кто), dónde (где), cuándo (когда), cómo (как), cuánto (сколько).","es-g34-u09.g.x.1":"Вопрос начинается с ¿ и заканчивается ?: ¿Dónde está el gato?","es-g34-u09.g.x.2":"Глагол обычно стоит сразу после вопросительного слова: ¿Qué comes? ¿Quién canta?","es-g34-u09.g.0":"Что ты ешь?","es-g34-u09.g.1":"Кто твой друг?","es-g34-u09.g.2":"Где мой рюкзак?","es-g34-u09.g.3":"Когда у тебя день рождения?","es-g34-u09.g.4":"Как дела?","es-g34-u09.g.4.task":'Преврати в вопрос с "¿Cómo…?"',"es-g34-u09.g.5":"Сколько стоит?","es-g34-u09.g.6":"Где живёт Лусия?","es-g34-u09.g.6.task":'Преврати в вопрос с "¿Dónde…?"',"es-g34-u09.g.7":"Что читает Матео?","es-g34-u09.g.7.task":'Преврати в вопрос с "¿Qué…?"',"es-g34-u10.title":"Нет, не делаю: отрицание","es-g34-u10.tip":'В испанском можно сказать "No … nada" — с двумя отрицаниями, и это правильно. Совсем как в русском!',"es-g34-u10.w.0":"ничего","es-g34-u10.w.1":"никогда","es-g34-u10.w.2":"никто","es-g34-u10.w.3":"всегда","es-g34-u10.w.4":"тоже","es-g34-u10.w.5":"тоже не","es-g34-u10.w.6":"ещё (пока нет)","es-g34-u10.w.7":"уже","es-g34-u10.w.8":"ложь","es-g34-u10.w.9":"правда","es-g34-u10.s.0":"Я не голоден.","es-g34-u10.s.1":"Мне не нравится холод.","es-g34-u10.s.2":"Я ничего не хочу.","es-g34-u10.s.3":"Я никогда не опаздываю.","es-g34-u10.s.4":"Здесь никого нет.","es-g34-u10.s.5":"Я тоже не иду.","es-g34-u10.s.6":"Я ещё не умею читать.","es-g34-u10.s.7":"Это неправда.","es-g34-u10.g.title":"Отрицание: no + глагол, nada, nunca, nadie","es-g34-u10.g.x.0":"Чтобы сказать «не…», ставь no перед глаголом: No como. No tengo gato.","es-g34-u10.g.x.1":"Если nada (ничего), nadie (никто), nunca (никогда) стоят после глагола, no тоже нужно: No veo nada.","es-g34-u10.g.x.2":"«Я тоже» — también, «я тоже нет» — tampoco.","es-g34-u10.g.0":"Я не голоден.","es-g34-u10.g.1":"Я ничего не вижу.","es-g34-u10.g.2":"Дома никого нет.","es-g34-u10.g.3":"Я никогда не ем конфеты.","es-g34-u10.g.4":"Я тоже не хочу.","es-g34-u10.g.5":"Мне не нравится дождь.","es-g34-u10.g.5.task":"Сделай предложение отрицательным (no)","es-g34-u10.g.6":"Она не ест мясо.","es-g34-u10.g.6.task":"Сделай предложение отрицательным (no)","es-g34-u10.g.7":"Я ничего не хочу.","es-g34-u10.g.7.task":'Сделай предложение отрицательным с "nada"',"es-g34-u11.title":"Есть, имеется: hay","es-g34-u11.tip":"hay — «есть, имеется», está — «находится (где-то)». Hay un gato (есть кот) / El gato está aquí (кот здесь).","es-g34-u11.w.0":"рынок","es-g34-u11.w.1":"магазин","es-g34-u11.w.2":"хлеб","es-g34-u11.w.3":"яйца","es-g34-u11.w.4":"фрукты","es-g34-u11.w.5":"молоко","es-g34-u11.w.6":"пакет (сумка)","es-g34-u11.w.7":"холодильник","es-g34-u11.w.8":"много","es-g34-u11.w.9":"мало","es-g34-u11.s.0":"В саду есть кот.","es-g34-u11.s.1":"На рынке много фруктов.","es-g34-u11.s.2":"В холодильнике нет молока.","es-g34-u11.s.3":"Хлеб есть?","es-g34-u11.s.4":"В пакете шесть яиц.","es-g34-u11.s.5":"Воды мало.","es-g34-u11.s.6":"В моём классе двадцать детей.","es-g34-u11.s.7":"Рядом есть магазин.","es-g34-u11.g.title":"hay: есть / нет","es-g34-u11.g.x.0":"«Есть, имеется» — одно слово hay. Один предмет или много — форма одна: Hay un gato. Hay tres gatos.","es-g34-u11.g.x.1":"Если нет — No hay: No hay leche.","es-g34-u11.g.x.2":"Для количества mucho/mucha (много), poco/poca (мало) согласуются с существительным: mucha fruta, pocos huevos.","es-g34-u11.g.0":"На улице есть собака.","es-g34-u11.g.1":"Здесь много магазинов.","es-g34-u11.g.2":"Хлеба нет.","es-g34-u11.g.3":"Фруктов много.","es-g34-u11.g.4":"Яиц мало.","es-g34-u11.g.5":"Дома нет молока.","es-g34-u11.g.5.task":"Сделай предложение отрицательным (no)","es-g34-u11.g.6":"Здесь есть холодильник?","es-g34-u11.g.6.task":"Преврати в вопрос","es-g34-u11.g.7":"В парке много детей.","es-g34-u11.g.7.task":'Перепиши с "muchos" (много)',"es-g34-u12.title":"Хочу есть, хочу пить: выражения с tener","es-g34-u12.tip":'Чтобы спросить возраст, говорят "¿Cuántos años tienes?" (сколько тебе лет?). Ответ: "Tengo … años."',"es-g34-u12.w.0":"голод","es-g34-u12.w.1":"жажда","es-g34-u12.w.2":"сонливость","es-g34-u12.w.3":"страх","es-g34-u12.w.4":"спешка","es-g34-u12.w.5":"удача","es-g34-u12.w.6":"правота","es-g34-u12.w.7":"годы (возраст)","es-g34-u12.w.8":"бутерброд","es-g34-u12.w.9":"одеяло","es-g34-u12.s.0":"Я голоден.","es-g34-u12.s.1":"Ты хочешь пить?","es-g34-u12.s.2":"Мне девять лет.","es-g34-u12.s.3":"Моя младшая сестра хочет спать.","es-g34-u12.s.4":"Мы спешим.","es-g34-u12.s.5":"Я не боюсь.","es-g34-u12.s.6":"Ты прав.","es-g34-u12.s.7":"Мне холодно, нужно одеяло.","es-g34-u12.g.title":"Выражения с tener: tengo hambre, tengo años","es-g34-u12.g.x.0":"tener — это «иметь», и голод, жажду и возраст по-испански тоже «имеют»: Tengo hambre. Tengo diez años.","es-g34-u12.g.x.1":"tengo, tienes, tiene, tenemos, tienen. Только yo особенный: tengo.","es-g34-u12.g.x.2":"tener frío (мне холодно), tener calor (мне жарко), tener sueño (хочу спать), tener miedo (боюсь), tener prisa (спешу), tener razón (прав).","es-g34-u12.g.0":"Я голоден.","es-g34-u12.g.1":"Ты хочешь пить?","es-g34-u12.g.2":"Ей восемь лет.","es-g34-u12.g.3":"Мы спешим.","es-g34-u12.g.4":"Они боятся.","es-g34-u12.g.5":"Моему дедушке семьдесят лет.","es-g34-u12.g.5.task":'Перепиши с "Mi abuelo … setenta"',"es-g34-u12.g.6":"Я не хочу спать.","es-g34-u12.g.6.task":"Сделай предложение отрицательным (no)","es-g34-u12.g.7":"Тебе холодно?","es-g34-u12.g.7.task":'Преврати в вопрос с "¿Tú…?"',"es-g34-u12.st.title":"Перемена","es-g34-u12.st.l.0":"Я очень голоден. У тебя есть бутерброд?","es-g34-u12.st.l.1":"Да, у меня два. Возьми один.","es-g34-u12.st.l.2":"Спасибо! И пить хочется.","es-g34-u12.st.l.3":"У фонтанчика есть вода. Сколько тебе лет, Пабло?","es-g34-u12.st.l.4":"Девять. А тебе?","es-g34-u12.st.l.5":"Мне десять. Поторопимся, урок скоро начнётся!","es-g34-u12.st.q.0":"Чего хочет Пабло?","es-g34-u12.st.q.0.o.0":"Книгу","es-g34-u12.st.q.0.o.1":"Бутерброд и воду","es-g34-u12.st.q.0.o.2":"Мяч","es-g34-u12.st.q.1":"Сколько лет Марте?","es-g34-u12.st.q.1.o.0":"Девять лет","es-g34-u12.st.q.1.o.1":"Десять лет","es-g34-u12.st.q.1.o.2":"Восемь лет","es-g34-u13.title":"ser или estar?","es-g34-u13.tip":"Если сомневаешься, спроси себя: «Он такой вообще?» → ser. «Он такой сейчас? Где он?» → estar.","es-g34-u13.w.0":"скучный","es-g34-u13.w.1":"весёлый (интересный)","es-g34-u13.w.2":"больной","es-g34-u13.w.3":"здоровый","es-g34-u13.w.4":"открытый","es-g34-u13.w.5":"закрытый","es-g34-u13.w.6":"горячий","es-g34-u13.w.7":"холодный","es-g34-u13.w.8":"молодой","es-g34-u13.w.9":"добрый","es-g34-u13.s.0":"Мой учитель молодой и добрый.","es-g34-u13.s.1":"Я сегодня болею.","es-g34-u13.s.2":"Суп горячий.","es-g34-u13.s.3":"Эта игра весёлая.","es-g34-u13.s.4":"Магазин закрыт.","es-g34-u13.s.5":"Лусия из Перу.","es-g34-u13.s.6":"Мы в школе.","es-g34-u13.s.7":"Мороженое холодное.","es-g34-u13.g.title":"Различаем ser и estar","es-g34-u13.g.x.0":"ser = какой вообще (имя, профессия, страна, характер, время): Soy alto. Es profesora. Son las dos.","es-g34-u13.g.x.1":"estar = состояние сейчас, место, настроение: Estoy enfermo. Está en casa. Están contentos.","es-g34-u13.g.x.2":"Одно и то же слово меняет смысл: Es aburrido (скучный человек) / Está aburrido (ему сейчас скучно).","es-g34-u13.g.0":"Мой папа — врач.","es-g34-u13.g.1":"Сегодня я устал.","es-g34-u13.g.2":"Дверь открыта.","es-g34-u13.g.3":"Мы мексиканцы.","es-g34-u13.g.4":"Кофе горячий.","es-g34-u13.g.5":"Она больна.","es-g34-u13.g.5.task":'Перепиши с "enferma" (больна)',"es-g34-u13.g.6":"Магазин закрыт.","es-g34-u13.g.6.task":'Перепиши с "cerrada" (закрыта)',"es-g34-u13.g.7":"Мои друзья весёлые.","es-g34-u13.g.7.task":"Поставь во множественное число","es-g34-u14.title":"Куда идёшь? ir + a","es-g34-u14.tip":'"¿Adónde vas?" значит «Куда ты идёшь?». Ответ начинается с Voy a…',"es-g34-u14.w.0":"идти (ехать)","es-g34-u14.w.1":"кинотеатр","es-g34-u14.w.2":"пляж","es-g34-u14.w.3":"супермаркет","es-g34-u14.w.4":"музей","es-g34-u14.w.5":"вокзал","es-g34-u14.w.6":"горы","es-g34-u14.w.7":"ресторан","es-g34-u14.w.8":"зоопарк","es-g34-u14.w.9":"выходные","es-g34-u14.s.0":"Я иду на пляж.","es-g34-u14.s.1":"Куда ты идёшь?","es-g34-u14.s.2":"Мы идём в кино.","es-g34-u14.s.3":"Мама идёт в супермаркет.","es-g34-u14.s.4":"Мои друзья идут в зоопарк.","es-g34-u14.s.5":"В выходные мы едем в горы.","es-g34-u14.s.6":"Я еду на вокзал на велосипеде.","es-g34-u14.s.7":"Ты идёшь сегодня в музей?","es-g34-u14.g.title":"Глагол ir и a / al","es-g34-u14.g.x.0":"«Идти» — ir: voy, vas, va, vamos, van. Он сильно меняется, так что выучи его целиком.","es-g34-u14.g.x.1":"Куда идёшь — говорим с a: Voy a la playa.","es-g34-u14.g.x.2":"a + el сливаются в al: Voy al cine. (a el cine ✗)","es-g34-u14.g.0":"Я иду в школу.","es-g34-u14.g.1":"Ты идёшь в парк?","es-g34-u14.g.2":"Она идёт в супермаркет.","es-g34-u14.g.2.task":'Перепиши так, чтобы предложение начиналось с "Ella"',"es-g34-u14.g.3":"Мы идём в кино.","es-g34-u14.g.4":"Я иду в музей.","es-g34-u14.g.5":"Я иду на пляж.","es-g34-u14.g.6":"Мы идём в зоопарк.","es-g34-u14.g.6.task":'Перепиши так, чтобы предложение начиналось с "Nosotros"',"es-g34-u14.g.7":"Они едут в горы.","es-g34-u14.g.7.task":'Перепиши так, чтобы предложение начиналось с "Ellos"',"es-g34-u14.st.title":"Планы на выходные","es-g34-u14.st.l.0":"Елена, куда ты идёшь в субботу?","es-g34-u14.st.l.1":"Я иду в зоопарк с семьёй. А ты?","es-g34-u14.st.l.2":"Я иду на пляж. Жарко ведь.","es-g34-u14.st.l.3":"Как здорово! В воскресенье мы идём в кино. Пойдёшь с нами?","es-g34-u14.st.l.4":"Да, пойду. Во сколько?","es-g34-u14.st.l.5":"В пять. Увидимся в воскресенье!","es-g34-u14.st.q.0":"Куда Карлос идёт в субботу?","es-g34-u14.st.q.0.o.0":"В зоопарк","es-g34-u14.st.q.0.o.1":"На пляж","es-g34-u14.st.q.0.o.2":"В кино","es-g34-u14.st.q.1":"Во сколько фильм в воскресенье?","es-g34-u14.st.q.1.o.0":"В три","es-g34-u14.st.q.1.o.1":"В четыре","es-g34-u14.st.q.1.o.2":"В пять","es-g34-u15.title":"Который час?","es-g34-u15.tip":"Смотри на часы и говори Son las… Не забудь: только про час дня говорят Es la una!","es-g34-u15.w.0":"час (время)","es-g34-u15.w.1":"часы","es-g34-u15.w.2":"минута","es-g34-u15.w.3":"полдень","es-g34-u15.w.4":"полночь","es-g34-u15.w.5":"рано","es-g34-u15.w.6":"поздно","es-g34-u15.w.7":"завтрак","es-g34-u15.w.8":"ужин","es-g34-u15.w.9":"перемена","es-g34-u15.s.0":"Который час?","es-g34-u15.s.1":"Час дня.","es-g34-u15.s.2":"Три часа.","es-g34-u15.s.3":"Половина шестого.","es-g34-u15.s.4":"Восемь пятнадцать.","es-g34-u15.s.5":"Завтрак в семь.","es-g34-u15.s.6":"Перемена в одиннадцать.","es-g34-u15.s.7":"Я встаю рано.","es-g34-u15.g.title":"Называем время: Es la una / Son las dos","es-g34-u15.g.x.0":"Только про час говорят Es la una, а начиная с двух — Son las dos, Son las tres…","es-g34-u15.g.x.1":"Минуты добавляют через y: Son las dos y diez (2:10). Половина — y media, четверть — y cuarto.","es-g34-u15.g.x.2":"«В … часов» — a las: La clase es a las nueve.","es-g34-u15.g.0":"Час дня.","es-g34-u15.g.1":"Четыре часа.","es-g34-u15.g.2":"Половина седьмого.","es-g34-u15.g.3":"Девять пятнадцать.","es-g34-u15.g.4":"Ужин в восемь.","es-g34-u15.g.5":"Десять часов.","es-g34-u15.g.5.task":"Напиши время на час позже","es-g34-u15.g.6":"Перемена в одиннадцать.","es-g34-u15.g.6.task":'Перепиши с "once" (одиннадцать)',"es-g34-u15.g.7":"Половина второго.","es-g34-u15.g.7.task":'Добавь "y media" (половина)',"es-g34-u16.title":"Этот, тот: este, ese, aquel","es-g34-u16.tip":"Покажи рукой. Если это у тебя в руке — este, если рядом с другом — ese, если далеко-далеко — aquel!","es-g34-u16.w.0":"этот","es-g34-u16.w.1":"тот (рядом)","es-g34-u16.w.2":"вон тот (далеко)","es-g34-u16.w.3":"рубашка","es-g34-u16.w.4":"юбка","es-g34-u16.w.5":"кепка","es-g34-u16.w.6":"цена","es-g34-u16.w.7":"дешёвый","es-g34-u16.w.8":"дорогой","es-g34-u16.w.9":"размер","es-g34-u16.s.0":"Эта книга моя.","es-g34-u16.s.1":"Та рубашка красивая.","es-g34-u16.s.2":"Вон та гора высокая.","es-g34-u16.s.3":"Сколько стоит эта кепка?","es-g34-u16.s.4":"Те часы очень дорогие.","es-g34-u16.s.5":"Эти ботинки дешёвые.","es-g34-u16.s.6":"Я хочу ту синюю юбку.","es-g34-u16.s.7":"Какого это размера?","es-g34-u16.g.title":"Указательные слова: este (этот), ese (тот), aquel (вон тот)","es-g34-u16.g.x.0":"Близко — este, чуть дальше — ese, очень далеко — aquel.","es-g34-u16.g.x.1":"Они согласуются с существительным: este libro / esta casa / estos libros / estas casas.","es-g34-u16.g.x.2":"ese → esa, esos, esas / aquel → aquella, aquellos, aquellas.","es-g34-u16.g.0":"Эта книга новая.","es-g34-u16.g.1":"Эта рубашка белая.","es-g34-u16.g.2":"Та собака большая.","es-g34-u16.g.3":"Вон тот дом старый.","es-g34-u16.g.4":"Эти ботинки дорогие.","es-g34-u16.g.5":"Те кепки дешёвые.","es-g34-u16.g.5.task":"Поставь во множественное число","es-g34-u16.g.6":"Та юбка красивая.","es-g34-u16.g.6.task":'Перепиши с "esa" (та)',"es-g34-u16.g.7":"Вон то дерево высокое.","es-g34-u16.g.7.task":'Перепиши с "aquel" (вон тот)',"es-g34-u17.title":"Хочу, могу: querer, poder","es-g34-u17.tip":'"¿Puedo…?" — так просят разрешения. ¿Puedo entrar? ¿Puedo salir?',"es-g34-u17.w.0":"хотеть","es-g34-u17.w.1":"мочь","es-g34-u17.w.2":"играть","es-g34-u17.w.3":"спать","es-g34-u17.w.4":"помогать","es-g34-u17.w.5":"выходить","es-g34-u17.w.6":"входить","es-g34-u17.w.7":"красить (рисовать красками)","es-g34-u17.w.8":"летать","es-g34-u17.w.9":"разрешение","es-g34-u17.s.0":"Я хочу поиграть с тобой.","es-g34-u17.s.1":"Хочешь мороженое?","es-g34-u17.s.2":"Сегодня я не могу выйти.","es-g34-u17.s.3":"Можно войти?","es-g34-u17.s.4":"Птицы умеют летать.","es-g34-u17.s.5":"Мы хотим покрасить стену.","es-g34-u17.s.6":"Мой младший брат хочет спать.","es-g34-u17.s.7":"Ты можешь помочь маме?","es-g34-u17.g.title":"querer (хотеть) и poder (мочь) + инфинитив","es-g34-u17.g.x.0":"querer: quiero, quieres, quiere, queremos, quieren. e меняется на ie (кроме nosotros).","es-g34-u17.g.x.1":"poder: puedo, puedes, puede, podemos, pueden. o меняется на ue (кроме nosotros).","es-g34-u17.g.x.2":"После них ставится глагол в начальной форме: Quiero comer. Puedo nadar.","es-g34-u17.g.0":"Я хочу играть.","es-g34-u17.g.1":"Хочешь мороженое?","es-g34-u17.g.2":"Она умеет плавать.","es-g34-u17.g.3":"Мы можем помочь.","es-g34-u17.g.4":"Они хотят выйти.","es-g34-u17.g.5":"Сегодня я не могу выйти.","es-g34-u17.g.5.task":"Сделай предложение отрицательным (no)","es-g34-u17.g.6":"Ты можешь порисовать красками со мной?","es-g34-u17.g.6.task":'Преврати в вопрос с "¿Tú…?"',"es-g34-u17.g.7":"Мы хотим спать.","es-g34-u17.g.7.task":'Перепиши так, чтобы предложение начиналось с "Nosotros"',"es-g34-u17.st.title":"Можно пойти погулять?","es-g34-u17.st.l.0":"Мама, можно я пойду на улицу поиграть?","es-g34-u17.st.l.1":"Хочешь играть прямо сейчас? Сначала уроки.","es-g34-u17.st.l.2":"Я уже сделал уроки. Могу помочь тебе на кухне!","es-g34-u17.st.l.3":"Очень хорошо. Можешь погулять один час.","es-g34-u17.st.l.4":"Спасибо! Хочу поиграть в футбол с Диего.","es-g34-u17.st.q.0":"Что мама велела сделать сначала?","es-g34-u17.st.q.0.o.0":"Уроки","es-g34-u17.st.q.0.o.1":"Ужин","es-g34-u17.st.q.0.o.2":"Дневной сон","es-g34-u17.st.q.1":"Сколько времени Уго может гулять?","es-g34-u17.st.q.1.o.0":"Тридцать минут","es-g34-u17.st.q.1.o.1":"Один час","es-g34-u17.st.q.1.o.2":"Два часа","es-g34-u18.title":"Месяцы, времена года и даты","es-g34-u18.tip":'Как и в русском, сначала число: "5 de mayo". Попробуй сказать свой день рождения по-испански!',"es-g34-u18.w.0":"январь","es-g34-u18.w.1":"апрель","es-g34-u18.w.2":"июль","es-g34-u18.w.3":"октябрь","es-g34-u18.w.4":"декабрь","es-g34-u18.w.5":"весна","es-g34-u18.w.6":"лето","es-g34-u18.w.7":"осень","es-g34-u18.w.8":"зима","es-g34-u18.w.9":"каникулы","es-g34-u18.s.0":"Сегодня 3 мая.","es-g34-u18.s.1":"Мой день рождения в июле.","es-g34-u18.s.2":"Зимой холодно.","es-g34-u18.s.3":"Весна прекрасна.","es-g34-u18.s.4":"Какое сегодня число?","es-g34-u18.s.5":"Каникулы летом.","es-g34-u18.s.6":"Осенью опадают листья.","es-g34-u18.s.7":"Декабрь — последний месяц.","es-g34-u18.g.title":"Называем дату: el + число + de + месяц","es-g34-u18.g.x.0":"В дате сначала число, потом месяц: Hoy es cinco de abril. (5 апреля)","es-g34-u18.g.x.1":"Только первое число — el primero: el primero de enero.","es-g34-u18.g.x.2":"Месяцы и времена года пишутся с маленькой буквы. «В месяце» — en: en julio, en verano.","es-g34-u18.g.0":"Сегодня 2 марта.","es-g34-u18.g.1":"Мой день рождения 10 июля.","es-g34-u18.g.2":"Сегодня 1 января.","es-g34-u18.g.3":"Летом жарко.","es-g34-u18.g.4":"Занятия начинаются в сентябре.","es-g34-u18.g.5":"Сегодня 5 апреля.","es-g34-u18.g.5.task":"Напиши дату следующего дня","es-g34-u18.g.6":"Зимой идёт снег.","es-g34-u18.g.6.task":'Перепиши с "invierno … nieva"',"es-g34-u18.g.7":"Мой день рождения в декабре.","es-g34-u18.g.7.task":'Перепиши с "diciembre"',"es-g34-u19.title":"Всегда, иногда: мой день","es-g34-u19.tip":"Расскажи о своём дне по-испански: Siempre…, normalmente…, a veces…, nunca….","es-g34-u19.w.0":"иногда","es-g34-u19.w.1":"обычно","es-g34-u19.w.2":"завтракать","es-g34-u19.w.3":"обедать","es-g34-u19.w.4":"ужинать","es-g34-u19.w.5":"отдыхать","es-g34-u19.w.6":"приходить","es-g34-u19.w.7":"смотреть","es-g34-u19.w.8":"телевизор","es-g34-u19.w.9":"распорядок дня","es-g34-u19.s.0":"Я всегда завтракаю в семь.","es-g34-u19.s.1":"Иногда я обедаю в школе.","es-g34-u19.s.2":"Обычно я прихожу домой в четыре.","es-g34-u19.s.3":"После обеда я немного отдыхаю.","es-g34-u19.s.4":"По утрам я никогда не смотрю телевизор.","es-g34-u19.s.5":"Мы ужинаем в восемь.","es-g34-u19.s.6":"По субботам я играю с двоюродными братьями.","es-g34-u19.s.7":"Мой распорядок дня простой.","es-g34-u19.g.title":"Слова частоты: siempre, normalmente, a veces, nunca","es-g34-u19.g.x.0":"Как часто: siempre (всегда) > normalmente (обычно) > a veces (иногда) > nunca (никогда).","es-g34-u19.g.x.1":"Обычно стоят в начале предложения или перед глаголом: Siempre desayuno. A veces como pizza.","es-g34-u19.g.x.2":"«По понедельникам» — los + день недели: los lunes, los sábados. «Утром» — por la mañana, «после обеда» — por la tarde.","es-g34-u19.g.0":"Я всегда завтракаю с семьёй.","es-g34-u19.g.1":"Иногда я ем в школе.","es-g34-u19.g.2":"Я никогда не опаздываю.","es-g34-u19.g.2.task":'Перепиши с "nunca" (никогда)',"es-g34-u19.g.3":"Обычно я ужинаю в восемь.","es-g34-u19.g.4":"По понедельникам у меня урок музыки.","es-g34-u19.g.5":"Утром я завтракаю.","es-g34-u19.g.6":"Я никогда не смотрю телевизор.","es-g34-u19.g.6.task":'Перепиши с "nunca" (никогда)',"es-g34-u19.g.7":"По субботам я отдыхаю.","es-g34-u19.g.7.task":"Перепиши с «каждую субботу» (los sábados)","es-g34-u20.title":"И, но, потому что","es-g34-u20.tip":'С pero и porque можно строить длинные предложения. "Quiero…, pero…" / "… porque …"',"es-g34-u20.w.0":"но","es-g34-u20.w.1":"потому что","es-g34-u20.w.2":"также","es-g34-u20.w.3":"тогда (значит)","es-g34-u20.w.4":"довольный","es-g34-u20.w.5":"усталый","es-g34-u20.w.6":"трудный","es-g34-u20.w.7":"лёгкий","es-g34-u20.w.8":"дождь","es-g34-u20.w.9":"прогулка","es-g34-u20.s.0":"У меня есть собака и кот.","es-g34-u20.s.1":"Я хочу выйти, но идёт дождь.","es-g34-u20.s.2":"Я не иду, потому что устал.","es-g34-u20.s.3":"Уроки трудные, но я их доделываю.","es-g34-u20.s.4":"Я рад, потому что сегодня пятница.","es-g34-u20.s.5":"Идёт дождь, значит, прогулки не будет.","es-g34-u20.s.6":"Я люблю читать и рисовать тоже.","es-g34-u20.s.7":"Контрольная лёгкая и короткая.","es-g34-u20.g.title":"Союзы y / pero / porque","es-g34-u20.g.x.0":"y (и) соединяет два слова: pan y leche. Если следующее слово начинается на i-, y превращается в e: padres e hijos.","es-g34-u20.g.x.1":"pero (но) соединяет противоположное: Es pequeño, pero fuerte.","es-g34-u20.g.x.2":"porque (потому что) объясняет причину: No salgo porque llueve. Пишется слитно, в отличие от вопроса ¿por qué?","es-g34-u20.g.0":"У меня есть хлеб и сыр.","es-g34-u20.g.1":"Он маленький, но сильный.","es-g34-u20.g.2":"Я не выхожу, потому что идёт дождь.","es-g34-u20.g.3":"Родители и дети играют вместе.","es-g34-u20.g.4":"Я устал, значит, отдыхаю.","es-g34-u20.g.5":"Я хочу играть, но у меня уроки.","es-g34-u20.g.5.task":'Соедини в одно предложение с помощью "pero"',"es-g34-u20.g.6":"Я счастлив, потому что сегодня суббота.","es-g34-u20.g.6.task":'Соедини в одно предложение с помощью "porque"',"es-g34-u20.g.7":"Я люблю читать и рисовать.","es-g34-u20.g.7.task":'Соедини в одно предложение с помощью "y"'},t={"es-g56-u01.title":"Я делаю, я выхожу: неправильные глаголы","es-g56-u01.tip":"В форме «я» — окончание -go: hago, salgo, pongo, traigo, vengo, digo. Выучи эти шесть как песенку.","es-g56-u01.w.0":"делать (мастерить)","es-g56-u01.w.1":"выходить","es-g56-u01.w.2":"класть","es-g56-u01.w.3":"приносить","es-g56-u01.w.4":"приходить","es-g56-u01.w.5":"говорить (сказать)","es-g56-u01.w.6":"знать (людей, места)","es-g56-u01.w.7":"домашнее задание","es-g56-u01.w.8":"рюкзак","es-g56-u01.w.9":"школьный двор","es-g56-u01.w.10":"полдник","es-g56-u01.w.11":"рано","es-g56-u01.s.0":"Я делаю домашнее задание после обеда.","es-g56-u01.s.1":"Я выхожу из дома в восемь.","es-g56-u01.s.2":"Я кладу рюкзак на стул.","es-g56-u01.s.3":"Я приношу полдник на школьный двор.","es-g56-u01.s.4":"Придёшь сегодня ко мне домой?","es-g56-u01.s.5":"Я всегда говорю правду.","es-g56-u01.s.6":"Я знаю всех соседей.","es-g56-u01.s.7":"Моя сестра рано заправляет постель.","es-g56-u01.g.title":"Глаголы с -go в форме yo: hago, salgo, pongo","es-g56-u01.g.x.0":"Hacer, salir, poner, traer, venir и decir заканчиваются на -go только в форме «я» (yo): hago, salgo, pongo, traigo, vengo, digo.","es-g56-u01.g.x.1":"В остальных формах они почти правильные: haces, hace, hacemos, hacen / sales, sale, salimos, salen.","es-g56-u01.g.x.2":"У venir и decir меняются и формы tú·él: vienes, viene / dices, dice. А conocer даёт conozco.","es-g56-u01.g.0":"Я делаю домашнее задание дома.","es-g56-u01.g.1":"Я выхожу в три.","es-g56-u01.g.2":"Я накрываю на стол.","es-g56-u01.g.3":"Я приношу хлеб.","es-g56-u01.g.4":"Ты идёшь со мной.","es-g56-u01.g.5":"Я иду из школы.","es-g56-u01.g.5.task":'Перепиши так, чтобы предложение начиналось с "Yo"',"es-g56-u01.g.6":"Я говорю правду.","es-g56-u01.g.6.task":'Перепиши так, чтобы предложение начиналось с "Yo"',"es-g56-u01.g.7":"Мы занимаемся спортом.","es-g56-u01.g.7.task":'Перепиши так, чтобы предложение начиналось с "Nosotros"',"es-g56-u01.r.ko":"День Матео","es-g56-u01.r.genre":"Рассказ из жизни","es-g56-u01.r.p.0":"Меня зовут Матео, мне одиннадцать лет. Я выхожу из дома без четверти восемь. Кладу книги и полдник в рюкзак и прощаюсь с бабушкой. Школа близко, поэтому я приезжаю на велосипеде.","es-g56-u01.r.p.1":"На перемене я выхожу во двор с Лусией. Она всегда приносит фрукты, а я приношу печенье. После уроков я делаю домашнее задание в библиотеке. Я знаю всех учителей, и учителя знают меня.","es-g56-u01.r.p.2":"Вечером я накрываю на стол и ужинаю с семьёй. Папа говорит, что я очень ответственный. Завтра я сделаю всё то же самое!","es-g56-u01.r.q.3.o.0":"полдник","es-g56-u01.r.q.3.o.1":"домашнее задание","es-g56-u01.r.q.3.o.2":"велосипед","es-g56-u01.r.q.3.o.3":"библиотека","es-g56-u02.title":"e→ie, o→ue: глаголы, меняющие форму","es-g56-u02.tip":"Только nosotros не меняется! В «empezamos, volvemos» гласная остаётся прежней.","es-g56-u02.w.0":"начинать","es-g56-u02.w.1":"думать","es-g56-u02.w.2":"понимать","es-g56-u02.w.3":"предпочитать","es-g56-u02.w.4":"возвращаться","es-g56-u02.w.5":"считать (рассказывать)","es-g56-u02.w.6":"помнить","es-g56-u02.w.7":"находить","es-g56-u02.w.8":"обед","es-g56-u02.w.9":"ключ","es-g56-u02.w.10":"карман","es-g56-u02.w.11":"урок","es-g56-u02.s.0":"Урок начинается в девять.","es-g56-u02.s.1":"Я думаю о бабушке и дедушке.","es-g56-u02.s.2":"Я не понимаю это слово.","es-g56-u02.s.3":"Я предпочитаю обедать дома.","es-g56-u02.s.4":"Я возвращаюсь домой в пять.","es-g56-u02.s.5":"Я считаю монеты в кармане.","es-g56-u02.s.6":"Помнишь вчерашний урок?","es-g56-u02.s.7":"Не могу найти свой ключ.","es-g56-u02.g.title":"Глаголы с чередованием гласной: e→ie, o→ue","es-g56-u02.g.x.0":"У некоторых глаголов меняется гласная в середине. e→ie: empiezo, piensas, entiende, prefieren.","es-g56-u02.g.x.1":"o→ue: vuelvo, cuentas, recuerda, encuentran.","es-g56-u02.g.x.2":"Форма nosotros не меняется: empezamos, volvemos. Представь сапожок (boot): все формы внутри, а nosotros — снаружи.","es-g56-u02.g.0":"Фильм начинается сейчас.","es-g56-u02.g.1":"Я думаю о тебе.","es-g56-u02.g.2":"Ты понимаешь урок?","es-g56-u02.g.3":"Мы возвращаемся поздно.","es-g56-u02.g.4":"Она считает до десяти.","es-g56-u02.g.5":"Я предпочитаю чай.","es-g56-u02.g.5.task":'Перепиши так, чтобы предложение начиналось с "Yo"',"es-g56-u02.g.6":"Они возвращаются домой.","es-g56-u02.g.6.task":'Перепиши так, чтобы предложение начиналось с "Ellos"',"es-g56-u02.g.7":"Я не помню его имени.","es-g56-u02.g.7.task":"Сделай предложение отрицательным (no)","es-g56-u03.title":"Встать и умыться: возвратные глаголы","es-g56-u03.tip":"Расскажи по порядку, что делаешь утром: Me despierto, me levanto, me ducho, me visto, me peino.","es-g56-u03.w.0":"вставать","es-g56-u03.w.1":"принимать душ","es-g56-u03.w.2":"одеваться","es-g56-u03.w.3":"причёсываться","es-g56-u03.w.4":"умываться","es-g56-u03.w.5":"ложиться спать","es-g56-u03.w.6":"просыпаться","es-g56-u03.w.7":"садиться","es-g56-u03.w.8":"щётка (зубная)","es-g56-u03.w.9":"полотенце","es-g56-u03.w.10":"зеркало","es-g56-u03.w.11":"пижама","es-g56-u03.s.0":"Я встаю в семь.","es-g56-u03.s.1":"Я принимаю душ и быстро одеваюсь.","es-g56-u03.s.2":"Мой брат причёсывается перед зеркалом.","es-g56-u03.s.3":"Мы моем руки перед едой.","es-g56-u03.s.4":"Я ложусь спать в половине десятого.","es-g56-u03.s.5":"Во сколько ты просыпаешься?","es-g56-u03.s.6":"Дети садятся на пол.","es-g56-u03.s.7":"Я вытираюсь синим полотенцем.","es-g56-u03.g.title":"Возвратные глаголы: me levanto, te duchas, se viste","es-g56-u03.g.x.0":"Если действие направлено на самого себя, перед глаголом ставят me, te, se, nos, se: Me levanto. Te duchas. Se viste.","es-g56-u03.g.x.1":"Если инфинитив заканчивается на -se, глагол возвратный: levantarse, acostarse.","es-g56-u03.g.x.2":"Частицу можно прикрепить и к концу инфинитива: Quiero levantarme. Voy a ducharme.","es-g56-u03.g.0":"Я встаю в семь.","es-g56-u03.g.1":"Ты принимаешь душ утром?","es-g56-u03.g.2":"Она одевается сама.","es-g56-u03.g.3":"Мы чистим зубы.","es-g56-u03.g.4":"Они ложатся спать поздно.","es-g56-u03.g.5":"Я просыпаюсь в шесть.","es-g56-u03.g.5.task":'Поставь в форму "Yo"',"es-g56-u03.g.6":"Мы садимся здесь.","es-g56-u03.g.6.task":'Поставь в форму "Nosotros"',"es-g56-u03.g.7":"Я хочу лечь спать пораньше.","es-g56-u03.g.7.task":'Перепиши с "Quiero + инфинитив"',"es-g56-u03.r.ko":"Утро Софии","es-g56-u03.r.genre":"Рассказ из жизни","es-g56-u03.r.p.0":"София просыпается без десяти семь, но встаёт только в семь. Сначала она принимает тёплый душ и вытирается жёлтым полотенцем. Потом одевается. Сегодня она выбирает синие брюки и белую футболку.","es-g56-u03.r.p.1":"В ванной она чистит зубы зелёной щёткой и причёсывается перед зеркалом. Её младший брат Уго всё ещё в пижаме. «Поторопись, Уго!» — говорит София. Уго садится на кровать и зевает.","es-g56-u03.r.p.2":"В восемь они вдвоём завтракают с мамой. Вечером София ложится спать в половине десятого. Перед сном она всегда немного читает.","es-g56-u03.r.q.4.o.0":"зевать","es-g56-u03.r.q.4.o.1":"петь","es-g56-u03.r.q.4.o.2":"бегать","es-g56-u03.r.q.4.o.3":"смеяться","es-g56-u04.title":"Я собираюсь…: ir a + инфинитив","es-g56-u04.tip":"Расскажи о планах на выходные по-испански: Voy a…, Vamos a…. А если планов нет — No voy a hacer nada!","es-g56-u04.w.0":"путешествовать","es-g56-u04.w.1":"навещать (посещать)","es-g56-u04.w.2":"покупать","es-g56-u04.w.3":"учиться (чему-то)","es-g56-u04.w.4":"плавать","es-g56-u04.w.5":"чемодан","es-g56-u04.w.6":"билет","es-g56-u04.w.7":"аэропорт","es-g56-u04.w.8":"гостиница","es-g56-u04.w.9":"карта","es-g56-u04.w.10":"следующий","es-g56-u04.w.11":"скоро","es-g56-u04.s.0":"Я собираюсь поехать в Мексику.","es-g56-u04.s.1":"Мы собираемся навестить бабушку и дедушку.","es-g56-u04.s.2":"Ты собираешься купить билет?","es-g56-u04.s.3":"Моя сестра собирается учить испанский.","es-g56-u04.s.4":"Следующим летом мы будем много плавать.","es-g56-u04.s.5":"Родители будут собирать чемоданы.","es-g56-u04.s.6":"Мы скоро приедем в аэропорт.","es-g56-u04.s.7":"Я не буду смотреть на карту.","es-g56-u04.g.title":"Ir a + инфинитив: ближайшее будущее","es-g56-u04.g.x.0":"«Собираюсь что-то сделать» — это глагол ir + a + инфинитив: Voy a comer. Vas a leer. Va a dormir.","es-g56-u04.g.x.1":"Если нас много: Vamos a…, Van a…. Отрицание: No voy a….","es-g56-u04.g.x.2":"Используй со словами времени: mañana (завтра), el próximo año (в следующем году), pronto (скоро), esta noche (сегодня вечером).","es-g56-u04.g.0":"Я собираюсь купить хлеб.","es-g56-u04.g.1":"Ты собираешься путешествовать летом?","es-g56-u04.g.2":"Она собирается посетить музей.","es-g56-u04.g.3":"Мы собираемся плавать.","es-g56-u04.g.4":"Они скоро приедут.","es-g56-u04.g.5":"Завтра я буду учиться плавать.","es-g56-u04.g.5.task":'Перепиши с "Mañana voy a…"',"es-g56-u04.g.6":"Я не буду покупать билет.","es-g56-u04.g.6.task":"Сделай предложение отрицательным (no)","es-g56-u04.g.7":"Мы собираемся навестить бабушку и дедушку.","es-g56-u04.g.7.task":'Перепиши в будущем с "Vamos a…"',"es-g56-u04.r.ko":"Путешествие семьи Руис","es-g56-u04.r.genre":"Рассказ из жизни","es-g56-u04.r.p.0":"Семья Руис в следующем месяце поедет в Перу. У папы уже есть билеты на самолёт, а мама сегодня вечером забронирует гостиницу. Двенадцатилетний Диего очень рад: он увидит Мачу-Пикчу.","es-g56-u04.r.p.1":"Его сестра Карла купит карту и новый фотоаппарат. «Я сделаю тысячу фотографий», — говорит она. Диего перед поездкой выучит десять слов на языке кечуа. В пятницу они оба будут собирать чемоданы.","es-g56-u04.r.p.2":"В субботу они очень рано отправятся в аэропорт. «Мы не опоздаем, — говорит папа. — И паспорта тоже не забудем!»","es-g56-u04.r.q.3.o.0":"бронировать","es-g56-u04.r.q.3.o.1":"покупать","es-g56-u04.r.q.3.o.2":"забывать","es-g56-u04.r.q.3.o.3":"фотографировать","es-g56-u05.title":"Вчера я…: прошедшее время -ar","es-g56-u05.tip":"В прошедшем yo — -é, él — -ó. Без ударения смысл меняется: canto (я пою) / cantó (он спел).","es-g56-u05.w.0":"вчера","es-g56-u05.w.1":"вчера вечером","es-g56-u05.w.2":"прошлый","es-g56-u05.w.3":"выигрывать","es-g56-u05.w.4":"танцевать","es-g56-u05.w.5":"петь","es-g56-u05.w.6":"готовить (еду)","es-g56-u05.w.7":"убирать","es-g56-u05.w.8":"матч","es-g56-u05.w.9":"команда","es-g56-u05.w.10":"экскурсия","es-g56-u05.w.11":"день рождения","es-g56-u05.s.0":"Вчера я играл в футбол со своей командой.","es-g56-u05.s.1":"Вчера вечером я ужинал с бабушкой и дедушкой.","es-g56-u05.s.2":"Ты выиграл матч?","es-g56-u05.s.3":"Моя сестра танцевала на празднике.","es-g56-u05.s.4":"Мы пели на дне рождения Лусии.","es-g56-u05.s.5":"Родители приготовили паэлью.","es-g56-u05.s.6":"В прошлую субботу я убрал свою комнату.","es-g56-u05.s.7":"Экскурсия закончилась в пять.","es-g56-u05.g.title":"Прошедшее время глаголов на -ar: hablé, hablaste, habló","es-g56-u05.g.x.0":"О законченных делах говорят в прошедшем времени (pretérito). Глаголы на -ar: habl-é, habl-aste, habl-ó, habl-amos, habl-aron.","es-g56-u05.g.x.1":"Yo — -é, él/ella — -ó. Ударение обязательно: canté, cantó.","es-g56-u05.g.x.2":"Форма nosotros такая же, как в настоящем (hablamos). Что это прошедшее, подскажут слова вроде ayer, anoche.","es-g56-u05.g.x.3":"У jugar форма yo пишется jugué (добавляем u, чтобы сохранить звук).","es-g56-u05.g.0":"Вчера я пел на уроке.","es-g56-u05.g.1":"Ты танцевал вчера вечером?","es-g56-u05.g.2":"Мой папа приготовил ужин.","es-g56-u05.g.3":"Мы вчера убрали дом.","es-g56-u05.g.4":"Они выиграли матч.","es-g56-u05.g.5":"Вчера я играл в футбол.","es-g56-u05.g.5.task":'Поставь в прошедшее время, добавив "Ayer"',"es-g56-u05.g.6":"Она поговорила с учительницей.","es-g56-u05.g.6.task":"Поставь в прошедшее время","es-g56-u05.g.7":"В прошлом году мы путешествовали на поезде.","es-g56-u05.g.7.task":'Перепиши так, чтобы предложение начиналось с "Nosotros"',"es-g56-u06.title":"Поел, пожил: прошедшее время -er/-ir","es-g56-u06.tip":"Прошедшее у -er и -ir совпадает полностью: comí/viví, comiste/viviste… Выучи один набор — и хватит!","es-g56-u06.w.0":"терять","es-g56-u06.w.1":"разбивать (ломать)","es-g56-u06.w.2":"учиться (узнавать новое)","es-g56-u06.w.3":"бегать","es-g56-u06.w.4":"открывать","es-g56-u06.w.5":"получать","es-g56-u06.w.6":"писать","es-g56-u06.w.7":"подниматься","es-g56-u06.w.8":"лестница","es-g56-u06.w.9":"приз","es-g56-u06.w.10":"конкурс","es-g56-u06.w.11":"сюрприз","es-g56-u06.s.0":"Вчера я потерял кепку в парке.","es-g56-u06.s.1":"Мой брат разбил стакан.","es-g56-u06.s.2":"Мы выучили новую песню.","es-g56-u06.s.3":"Ты бежал в забеге?","es-g56-u06.s.4":"Я открыл дверь и увидел сюрприз.","es-g56-u06.s.5":"Лусия получила приз на конкурсе.","es-g56-u06.s.6":"Я написал письмо дедушке.","es-g56-u06.s.7":"Мы взбежали по лестнице.","es-g56-u06.g.title":"Прошедшее время глаголов на -er / -ir: comí, comiste, comió","es-g56-u06.g.x.0":"У глаголов на -er и -ir прошедшее время одинаковое: com-í, com-iste, com-ió, com-imos, com-ieron.","es-g56-u06.g.x.1":"viv-í, viv-iste, viv-ió, viv-imos, viv-ieron.","es-g56-u06.g.x.2":"Yo — -í, él/ella — -ió. Не забывай ударение: perdí, perdió.","es-g56-u06.g.0":"Вчера я ел паэлью.","es-g56-u06.g.1":"Ты потерял ключ?","es-g56-u06.g.2":"Он разбил окно.","es-g56-u06.g.3":"Мы многому научились.","es-g56-u06.g.4":"Они открыли подарки.","es-g56-u06.g.5":"Она получила приз.","es-g56-u06.g.5.task":"Поставь в прошедшее время","es-g56-u06.g.6":"Я написал письмо.","es-g56-u06.g.6.task":"Поставь в прошедшее время","es-g56-u06.g.7":"Вчера мы поднялись на гору.","es-g56-u06.g.7.task":'Перепиши так, чтобы предложение начиналось с "Nosotros"',"es-g56-u06.r.ko":"Конкурс рисунков","es-g56-u06.r.genre":"Сказка","es-g56-u06.r.p.0":"В прошлый понедельник в школе устроили конкурс рисунков. Лусия нарисовала зелёного дракона с огромными крыльями. Пабло нарисовал своего пса Тоби, но случайно сломал красный карандаш и попросил у учительницы другой.","es-g56-u06.r.p.1":"В конце дня директор открыла конверт и прочитала имена. «Первый приз получает… Лусия!» Лусия получила коробку цветных карандашей и книгу. Пабло не выиграл, но понял кое-что важное: рисовать нужно аккуратно.","es-g56-u06.r.p.2":"В тот вечер Лусия написала письмо бабушке. «Бабушка, я выиграла конкурс. Вот это был сюрприз!» А Пабло решил к следующему году нарисовать дракона.","es-g56-u07.title":"Ешь! Открой!: повелительное наклонение","es-g56-u07.tip":"Команды короткие и бодрые! Попробуй дома: ¡Ven! ¡Mira! ¡Escucha! (А с por favor ещё лучше.)","es-g56-u07.w.0":"слушать","es-g56-u07.w.1":"смотреть","es-g56-u07.w.2":"ждать","es-g56-u07.w.3":"закрывать","es-g56-u07.w.4":"брать (пить)","es-g56-u07.w.5":"передавать (проходить)","es-g56-u07.w.6":"осторожность","es-g56-u07.w.7":"тишина","es-g56-u07.w.8":"медленно","es-g56-u07.w.9":"соль","es-g56-u07.w.10":"рецепт","es-g56-u07.w.11":"указание (инструкция)","es-g56-u07.s.0":"Слушай учительницу.","es-g56-u07.s.1":"Посмотри на карту, пожалуйста.","es-g56-u07.s.2":"Подожди минутку.","es-g56-u07.s.3":"Закрой окно, холодно.","es-g56-u07.s.4":"Выпей стакан воды.","es-g56-u07.s.5":"Передай мне соль, пожалуйста.","es-g56-u07.s.6":"Говори медленно и аккуратно.","es-g56-u07.s.7":"Прочитай рецепт, прежде чем готовить.","es-g56-u07.g.title":"Повеление для tú: ¡Habla! ¡Come! ¡Abre!","es-g56-u07.g.x.0":"Чтобы сказать другу «Сделай!», бери форму él/ella настоящего времени: habla, come, abre, escucha, cierra.","es-g56-u07.g.x.1":"Несколько неправильных нужно запомнить: ten (возьми), ven (иди сюда), pon (положи), sal (выйди), haz (сделай), di (скажи).","es-g56-u07.g.x.2":"Слова вроде me, la прикрепляются к концу: Pásame la sal. Ciérrala.","es-g56-u07.g.0":"Послушай песню!","es-g56-u07.g.1":"Съешь фрукты!","es-g56-u07.g.2":"Открой книгу!","es-g56-u07.g.3":"Иди сюда, пожалуйста!","es-g56-u07.g.4":"Накрой на стол!","es-g56-u07.g.5":"Закрой дверь!","es-g56-u07.g.5.task":"Преврати в команду","es-g56-u07.g.6":"Посмотри на карту!","es-g56-u07.g.6.task":"Преврати в команду","es-g56-u07.g.7":"Сделай домашнее задание сейчас же!","es-g56-u07.g.7.task":"Преврати в команду","es-g56-u08.title":"Больше, дешевле: сравниваем","es-g56-u08.tip":"Сравни родных и друзей: Mi papá es más alto que mi mamá. Soy tan rápido como mi amigo.","es-g56-u08.w.0":"больше (более)","es-g56-u08.w.1":"меньше (менее)","es-g56-u08.w.2":"лучше","es-g56-u08.w.3":"хуже","es-g56-u08.w.4":"старше","es-g56-u08.w.5":"младше","es-g56-u08.w.6":"широкий","es-g56-u08.w.7":"узкий","es-g56-u08.w.8":"шумный","es-g56-u08.w.9":"тихий (спокойный)","es-g56-u08.w.10":"здание","es-g56-u08.w.11":"житель","es-g56-u08.s.0":"Мадрид больше, чем Толедо.","es-g56-u08.s.1":"Посёлок менее шумный, чем город.","es-g56-u08.s.2":"Мой брат старше меня.","es-g56-u08.s.3":"Эта книга лучше той.","es-g56-u08.s.4":"Улица такая же узкая, как коридор.","es-g56-u08.s.5":"У меня столько же карандашей, сколько у тебя.","es-g56-u08.s.6":"Новое здание выше церкви.","es-g56-u08.s.7":"Мой младший двоюродный брат бегает быстрее меня.","es-g56-u08.g.title":"Сравнение: más … que, menos … que, tan … como","es-g56-u08.g.x.0":"«Более …, чем»: más + прилагательное + que. Soy más alto que tú.","es-g56-u08.g.x.1":"«Менее …, чем»: menos + прилагательное + que. «Такой же …, как»: tan + прилагательное + como.","es-g56-u08.g.x.2":"Особые формы: bueno → mejor, malo → peor, grande (о возрасте) → mayor, pequeño (о возрасте) → menor.","es-g56-u08.g.0":"Лев больше кошки.","es-g56-u08.g.1":"Поезд менее быстрый, чем самолёт.","es-g56-u08.g.2":"Мой дом такой же красивый, как твой.","es-g56-u08.g.3":"Это мороженое вкуснее того.","es-g56-u08.g.4":"Моя сестра старше меня.","es-g56-u08.g.5":"Город более шумный, чем посёлок.","es-g56-u08.g.5.task":'Перепиши как "La ciudad … ruidosa"',"es-g56-u08.g.6":"Сегодня менее холодно, чем вчера.","es-g56-u08.g.6.task":'Перепиши с "menos" (менее)',"es-g56-u08.g.7":"Я такого же роста, как мой двоюродный брат.","es-g56-u08.g.7.task":'Перепиши с "tan … como" (такой же … как)',"es-g56-u08.r.ko":"Два города, двоюродные брат и сестра","es-g56-u08.r.genre":"Познавательный текст","es-g56-u08.r.p.0":"Хавьер живёт в Мадриде, а его двоюродная сестра Элена — в Куэнке. Мадрид намного больше Куэнки: в нём больше трёх миллионов жителей, а в Куэнке нет и шестидесяти тысяч. В Мадриде здания выше, улицы шире, а шума гораздо больше.","es-g56-u08.r.p.1":"Куэнка тише и старше. Её улицы такие узкие, что иногда машина не может проехать. Элена говорит, что воздух в Куэнке лучше, чем в Мадриде. Хавьер говорит, что в Мадриде интереснее, потому что там больше музеев и парков.","es-g56-u08.r.p.2":"Брат и сестра одного возраста и дружат так же крепко, как родные. Летом Хавьер приезжает в Куэнку, а зимой Элена — в Мадрид. Так они оба узнают самое лучшее в каждом городе.","es-g56-u08.r.q.3.o.0":"старинный","es-g56-u08.r.q.3.o.1":"шумный","es-g56-u08.r.q.3.o.2":"широкий","es-g56-u08.r.q.3.o.3":"новый","es-g56-u09.title":"Самый большой, самый лучший: превосходная степень","es-g56-u09.tip":"Назови мировые рекорды по-испански: el más alto, el más rápido, el más grande del mundo.","es-g56-u09.w.0":"длинный","es-g56-u09.w.1":"короткий","es-g56-u09.w.2":"глубокий","es-g56-u09.w.3":"знаменитый","es-g56-u09.w.4":"древний","es-g56-u09.w.5":"современный","es-g56-u09.w.6":"очень вкусный","es-g56-u09.w.7":"опасный","es-g56-u09.w.8":"мир","es-g56-u09.w.9":"планета","es-g56-u09.w.10":"животное","es-g56-u09.w.11":"пустыня","es-g56-u09.s.0":"Нил — самая длинная река в мире.","es-g56-u09.s.1":"Юпитер — самая большая планета.","es-g56-u09.s.2":"Синий кит — самое тяжёлое животное.","es-g56-u09.s.3":"Это самая вкусная пицца в городе.","es-g56-u09.s.4":"Моя бабушка — самый добрый человек из всех, кого я знаю.","es-g56-u09.s.5":"Это самое старое здание в городке.","es-g56-u09.s.6":"Сахара — самая знаменитая пустыня.","es-g56-u09.s.7":"Это наименее опасная дорога.","es-g56-u09.g.title":"Превосходная степень: el/la más … de","es-g56-u09.g.x.0":"«Самый …» — это el/la/los/las + más + прилагательное: el río más largo, la casa más bonita.","es-g56-u09.g.x.1":"«В …, из …» — это de: el más alto de la clase (самый высокий в классе).","es-g56-u09.g.x.2":"«Наименее …» — это menos. Особые формы: el mejor (самый лучший), el peor (самый плохой), el mayor (самый старший).","es-g56-u09.g.0":"Это самая длинная река в мире.","es-g56-u09.g.1":"Это самый древний город в Испании.","es-g56-u09.g.2":"Она лучший игрок в команде.","es-g56-u09.g.3":"Это самое опасное животное в море.","es-g56-u09.g.4":"Мой брат — самый старший в семье.","es-g56-u09.g.5":"Это наименее опасная дорога.","es-g56-u09.g.5.task":'Перепиши с "menos" (наименее)',"es-g56-u09.g.6":"Это самая высокая гора в стране.","es-g56-u09.g.6.task":'Поставь в превосходную степень: "la … más alta del país"',"es-g56-u09.g.7":"Это самый вкусный торт на празднике.","es-g56-u09.g.7.task":'Поставь в превосходную степень: "el … más delicioso de la fiesta"',"es-g56-u10.title":"Я его вижу: lo, la, los, las","es-g56-u10.tip":"Смотри на род и число предмета: el libro → lo, la carta → la, los lápices → los, las gafas → las.","es-g56-u10.w.0":"искать","es-g56-u10.w.1":"брать с собой (нести)","es-g56-u10.w.2":"использовать","es-g56-u10.w.3":"хранить","es-g56-u10.w.4":"одалживать","es-g56-u10.w.5":"нуждаться","es-g56-u10.w.6":"приглашать","es-g56-u10.w.7":"компьютер","es-g56-u10.w.8":"фотоаппарат","es-g56-u10.w.9":"очки","es-g56-u10.w.10":"зонт","es-g56-u10.w.11":"кошелёк","es-g56-u10.s.0":"Где мой кошелёк? Не могу его найти.","es-g56-u10.s.1":"Мне нужен зонт. Сегодня возьму его с собой.","es-g56-u10.s.2":"Очки? Я храню их в рюкзаке.","es-g56-u10.s.3":"Приезжают двоюродные братья. Приглашу их на ужин.","es-g56-u10.s.4":"Одолжишь мне фотоаппарат? Он мне нужен.","es-g56-u10.s.5":"Компьютер старый, но я пользуюсь им каждый день.","es-g56-u10.s.6":"Я ищу ключи. Ты их видишь?","es-g56-u10.s.7":"Я приглашаю тебя на свой праздник.","es-g56-u10.g.title":"Местоимения прямого дополнения: lo, la, los, las, me, te","es-g56-u10.g.x.0":"Чтобы не повторять слово, «его/её» — это lo (мужской род) / la (женский род), а «их» — los/las: ¿El libro? Lo leo. ¿La carta? La escribo.","es-g56-u10.g.x.1":"«Меня» — me, «тебя» — te: Te invito. Me buscas.","es-g56-u10.g.x.2":"Местоимение стоит перед глаголом. Если есть инфинитив, его можно прикрепить к концу: Quiero comprarlo.","es-g56-u10.g.0":"Книга? Читаю её сегодня вечером.","es-g56-u10.g.1":"Письмо? Напишу его завтра.","es-g56-u10.g.2":"Карандаши? Храню их здесь.","es-g56-u10.g.3":"Очки? Они мне нужны.","es-g56-u10.g.4":"Я приглашаю тебя к себе домой.","es-g56-u10.g.5":"Зонт? Я возьму его с собой.","es-g56-u10.g.5.task":'Замени "el paraguas" на lo',"es-g56-u10.g.6":"Фотоаппарат? Я часто им пользуюсь.","es-g56-u10.g.6.task":'Замени "la cámara" на la',"es-g56-u10.g.7":"Двоюродные братья? Я их приглашу.","es-g56-u10.g.7.task":'Замени "los primos" на los',"es-g56-u11.title":"Прямо сейчас: estar + -ando/-iendo","es-g56-u11.tip":"Оглянись вокруг и расскажи: Mamá está cocinando. El perro está durmiendo. ¿Qué estás haciendo tú?","es-g56-u11.w.0":"сейчас","es-g56-u11.w.1":"ещё (всё ещё)","es-g56-u11.w.2":"готовить (подготавливать)","es-g56-u11.w.3":"строить","es-g56-u11.w.4":"красить (рисовать)","es-g56-u11.w.5":"играть (на инструменте), трогать","es-g56-u11.w.6":"смеяться","es-g56-u11.w.7":"плакать","es-g56-u11.w.8":"ярмарка","es-g56-u11.w.9":"гитара","es-g56-u11.w.10":"клоун","es-g56-u11.w.11":"воздушный шарик","es-g56-u11.s.0":"Сейчас я делаю домашнее задание.","es-g56-u11.s.1":"Что ты ешь?","es-g56-u11.s.2":"Мама готовит ужин.","es-g56-u11.s.3":"Дети строят замок из песка.","es-g56-u11.s.4":"Мой брат играет на гитаре.","es-g56-u11.s.5":"Клоун смеётся вместе с детьми.","es-g56-u11.s.6":"Мы всё ещё красим стену.","es-g56-u11.s.7":"Малыш плачет, потому что потерял шарик.","es-g56-u11.g.title":"Действие прямо сейчас: estar + -ando / -iendo","es-g56-u11.g.x.0":"«Сейчас делаю» — это estar + форма глагола на -ando (-ar) / -iendo (-er, -ir): Estoy hablando. Estás comiendo. Está escribiendo.","es-g56-u11.g.x.1":"i между гласными превращается в y: leer → leyendo, construir → construyendo. А ещё dormir → durmiendo, reír → riendo.","es-g56-u11.g.x.2":"По лицам меняется только estar, а -ando/-iendo остаётся как есть.","es-g56-u11.g.0":"Я разговариваю с мамой.","es-g56-u11.g.1":"Ты ешь?","es-g56-u11.g.2":"Она пишет письмо.","es-g56-u11.g.3":"Мы читаем книгу.","es-g56-u11.g.4":"Они строят дом.","es-g56-u11.g.5":"Мой брат спит.","es-g56-u11.g.5.task":"Перепиши как действие прямо сейчас (estar + -ando/-iendo)","es-g56-u11.g.6":"Сейчас я крашу дверь.","es-g56-u11.g.6.task":'Перепиши с "Ahora estoy…"',"es-g56-u11.g.7":"Дети смеются.","es-g56-u11.g.7.task":"Перепиши как действие прямо сейчас (estar + -ando/-iendo)","es-g56-u11.r.ko":"Ярмарка в городке","es-g56-u11.r.genre":"Описание","es-g56-u11.r.p.0":"Субботний день, ярмарка в городке полна людей. На площади клоун с красным носом делает зверей из воздушных шариков. Дети смеются и кричат: «Собачка! Жираф!»","es-g56-u11.r.p.1":"У фонтана трое музыкантов играют на гитарах, а одна женщина поёт старую песню. Дедушка танцует с бабушкой. Мама готовит горячий шоколад у прилавка, а папа покупает чуррос.","es-g56-u11.r.p.2":"Я сижу на скамейке с сестрой. Она рисует в блокноте то, что видит. Один малыш плачет, потому что его шарик улетает в небо. И все смотрят на этот шарик!","es-g56-u11.r.q.3.o.0":"прилавок","es-g56-u11.r.q.3.o.1":"фонтан","es-g56-u11.r.q.3.o.2":"скамейка","es-g56-u11.r.q.3.o.3":"площадь","es-g56-u12.title":"Пошёл, сделал, был: неправильное прошедшее","es-g56-u12.tip":"У ir и ser прошедшее одинаковое — fui! Различай по смыслу: Fui al cine (пошёл) / Fui feliz (был счастлив).","es-g56-u12.w.0":"родиться","es-g56-u12.w.1":"расти","es-g56-u12.w.2":"изобретать","es-g56-u12.w.3":"открывать (совершать открытие)","es-g56-u12.w.4":"художник","es-g56-u12.w.5":"учёная (женщина)","es-g56-u12.w.6":"век","es-g56-u12.w.7":"история","es-g56-u12.w.8":"путешествие","es-g56-u12.w.9":"корабль","es-g56-u12.w.10":"король","es-g56-u12.w.11":"картина","es-g56-u12.s.0":"Вчера я ходил в музей с одноклассниками.","es-g56-u12.s.1":"Пикассо был очень знаменитым художником.","es-g56-u12.s.2":"Мария Кюри сделала важные открытия.","es-g56-u12.s.3":"Колумб совершил долгое путешествие на корабле.","es-g56-u12.s.4":"Мой дедушка прожил счастливую жизнь.","es-g56-u12.s.5":"Где ты был вчера?","es-g56-u12.s.6":"Этот король жил в пятнадцатом веке.","es-g56-u12.s.7":"Мы ходили смотреть старинную картину.","es-g56-u12.g.title":"Неправильное прошедшее: fui, hice, tuve, estuve","es-g56-u12.g.x.0":"У ir и ser прошедшее время одинаковое: fui, fuiste, fue, fuimos, fueron. (пошёл / был)","es-g56-u12.g.x.1":"hacer: hice, hiciste, hizo, hicimos, hicieron. tener: tuve, tuviste, tuvo, tuvimos, tuvieron.","es-g56-u12.g.x.2":"estar: estuve, estuviste, estuvo, estuvimos, estuvieron. В этих формах прошедшего нет ударения.","es-g56-u12.g.0":"Вчера я ходил в парк.","es-g56-u12.g.1":"Пикассо был великим художником.","es-g56-u12.g.2":"Что ты делал в воскресенье?","es-g56-u12.g.3":"Она испекла торт.","es-g56-u12.g.4":"У нас была контрольная.","es-g56-u12.g.5":"Вчера вечером я был дома.","es-g56-u12.g.5.task":'Поставь в прошедшее время, добавив "anoche"',"es-g56-u12.g.6":"Они ходили на пляж.","es-g56-u12.g.6.task":"Поставь в прошедшее время","es-g56-u12.g.7":"У моей бабушки было пятеро детей.","es-g56-u12.g.7.task":"Поставь в прошедшее время","es-g56-u12.r.ko":"Фрида Кало, художница красок","es-g56-u12.r.genre":"Биография","es-g56-u12.r.p.0":"Фрида Кало родилась в Мексике в 1907 году. В детстве она болела, а через несколько лет попала в серьёзную аварию в автобусе. Много месяцев она пролежала в постели. Папа подарил ей краски и зеркало — так Фрида начала рисовать.","es-g56-u12.r.p.1":"Фрида написала много автопортретов: с цветами в волосах и очень яркими красками. Она рисовала и животных, которые жили в её синем доме, — обезьян, собак, попугаев. Она побывала в США и во Франции, и её картины стали знамениты на весь мир.","es-g56-u12.r.p.2":"Фрида умерла в 1954 году, но её синий дом сегодня — музей. Каждый год тысячи людей приезжают туда, чтобы увидеть её картины и сад.","es-g56-u12.r.q.4.o.0":"серьёзный","es-g56-u12.r.q.4.o.1":"маленький","es-g56-u12.r.q.4.o.2":"весёлый","es-g56-u12.r.q.4.o.3":"синий","es-g56-u13.title":"Я знаю: saber и conocer","es-g56-u13.tip":"«Умею» — всегда saber: Sé nadar. «Бывал там, знаком с кем-то» — conocer.","es-g56-u13.w.0":"знать (факты, уметь)","es-g56-u13.w.1":"знать (людей, места)","es-g56-u13.w.2":"ответ","es-g56-u13.w.3":"адрес (направление)","es-g56-u13.w.4":"дорога (путь)","es-g56-u13.w.5":"язык","es-g56-u13.w.6":"соседка","es-g56-u13.w.7":"секрет","es-g56-u13.w.8":"число (номер)","es-g56-u13.w.9":"ездить (кататься)","es-g56-u13.w.10":"играть (на инструменте)","es-g56-u13.w.11":"столица","es-g56-u13.s.0":"Я умею плавать и кататься на велосипеде.","es-g56-u13.s.1":"Ты знаешь ответ?","es-g56-u13.s.2":"Я знаю твою соседку, она очень добрая.","es-g56-u13.s.3":"Я ещё не бывал в Барселоне.","es-g56-u13.s.4":"Моя тётя знает три языка.","es-g56-u13.s.5":"Знаешь, какая столица у Перу?","es-g56-u13.s.6":"Я не знаю твой номер телефона.","es-g56-u13.s.7":"Я знаю один секрет, но не скажу.","es-g56-u13.g.title":"Saber (факты, умения) и conocer (люди, места)","es-g56-u13.g.x.0":"Если знаешь факт или умеешь что-то — saber: Sé la respuesta. Sé nadar. (sé, sabes, sabe, sabemos, saben)","es-g56-u13.g.x.1":"Если знаком с человеком или бывал в каком-то месте — conocer: Conozco a Lucía. Conozco Madrid. (conozco, conoces, conoce…)","es-g56-u13.g.x.2":"Перед человеком ставь a: Conozco a tu hermano.","es-g56-u13.g.0":"Я знаю ответ.","es-g56-u13.g.1":"Я знаю твою учительницу.","es-g56-u13.g.2":"Ты умеешь плавать?","es-g56-u13.g.3":"Она очень хорошо знает Мадрид.","es-g56-u13.g.4":"Мы знаем адрес.","es-g56-u13.g.5":"Я знаю твою соседку.","es-g56-u13.g.5.task":'Перепиши с "a tu vecina" (это человек)',"es-g56-u13.g.6":"Я не умею играть на гитаре.","es-g56-u13.g.6.task":"Сделай предложение отрицательным (no)","es-g56-u13.g.7":"Знаешь, какая столица?","es-g56-u13.g.7.task":'Преврати в вопрос с "¿Tú…?"',"es-g56-u14.title":"Не делай!: отрицательное повеление","es-g56-u14.tip":"Утверждение — habla/come, отрицание — no hables/no comas. Запомни: гласные меняются местами.","es-g56-u14.w.0":"кричать","es-g56-u14.w.1":"трогать","es-g56-u14.w.2":"бегать","es-g56-u14.w.3":"забывать","es-g56-u14.w.4":"мешать (беспокоить)","es-g56-u14.w.5":"бросать (выбрасывать)","es-g56-u14.w.6":"запрещено","es-g56-u14.w.7":"правило","es-g56-u14.w.8":"коридор","es-g56-u14.w.9":"мусор","es-g56-u14.w.10":"мусорное ведро","es-g56-u14.w.11":"табличка (плакат)","es-g56-u14.s.0":"Не кричи в библиотеке.","es-g56-u14.s.1":"Не трогай картину, пожалуйста.","es-g56-u14.s.2":"Не бегай по коридору.","es-g56-u14.s.3":"Не забудь рюкзак.","es-g56-u14.s.4":"Не мешай собаке, когда она ест.","es-g56-u14.s.5":"Не бросай мусор на пол.","es-g56-u14.s.6":"Есть на уроке запрещено.","es-g56-u14.s.7":"На табличке написано: «Вход воспрещён».","es-g56-u14.g.title":"Отрицательное повеление: No hables. No comas. No abras.","es-g56-u14.g.x.0":"«Не делай» — это no + особая форма: у глаголов на -ar окончание -es, у -er/-ir — -as. No hables. No comas. No abras.","es-g56-u14.g.x.1":"Гласная противоположна утверждению: ¡Habla! ↔ No hables. ¡Come! ↔ No comas.","es-g56-u14.g.x.2":"Иногда меняется написание, чтобы сохранить звук: tocar → No toques. jugar → No juegues.","es-g56-u14.g.0":"Не кричи, пожалуйста.","es-g56-u14.g.1":"Не ешь на уроке.","es-g56-u14.g.2":"Не открывай окно.","es-g56-u14.g.3":"Не трогай это.","es-g56-u14.g.4":"Не играй с огнём.","es-g56-u14.g.5":"Не бегай по коридору.","es-g56-u14.g.5.task":"Преврати в запрет (отрицательное повеление)","es-g56-u14.g.6":"Не забудь зонт.","es-g56-u14.g.6.task":"Преврати в запрет (отрицательное повеление)","es-g56-u14.g.7":"Не бросай бумажки на пол.","es-g56-u14.g.7.task":"Преврати в запрет (отрицательное повеление)","es-g56-u15.title":"Por и para","es-g56-u15.tip":'Para смотрит вперёд (цель), а por — назад (причина). "Es para ti" / "Gracias por venir".',"es-g56-u15.w.0":"подарок","es-g56-u15.w.1":"причина","es-g56-u15.w.2":"цель","es-g56-u15.w.3":"окно","es-g56-u15.w.4":"почта (электронная)","es-g56-u15.w.5":"день (после полудня)","es-g56-u15.w.6":"неделя","es-g56-u15.w.7":"цена","es-g56-u15.w.8":"евро","es-g56-u15.w.9":"поезд","es-g56-u15.w.10":"лес","es-g56-u15.w.11":"утро (завтра)","es-g56-u15.s.0":"Этот подарок для тебя.","es-g56-u15.s.1":"Я учу испанский, чтобы поехать в Мексику.","es-g56-u15.s.2":"Спасибо за помощь.","es-g56-u15.s.3":"Мы идём через лес.","es-g56-u15.s.4":"Я купил эту книгу за 10 евро.","es-g56-u15.s.5":"После обеда я играю в футбол.","es-g56-u15.s.6":"Домашнее задание — к понедельнику.","es-g56-u15.s.7":"Я отправляю письмо по почте.","es-g56-u15.g.title":"Por (причина, через, цена) и para (цель, для кого, срок)","es-g56-u15.g.x.0":"para = «для, чтобы, к (сроку)»: Es para ti. Estudio para aprender. Es para el lunes.","es-g56-u15.g.x.1":"por = «за (что-то), через, за (цену)»: Gracias por todo. Paso por el parque. Lo compré por dos euros.","es-g56-u15.g.x.2":"Время суток — с por: por la mañana, por la tarde, por la noche.","es-g56-u15.g.0":"Этот подарок для бабушки.","es-g56-u15.g.1":"Спасибо за подарок.","es-g56-u15.g.2":"Я учусь, чтобы стать врачом.","es-g56-u15.g.3":"Мы гуляем по пляжу.","es-g56-u15.g.4":"Утром я завтракаю.","es-g56-u15.g.5":"Домашнее задание — к завтрашнему дню.","es-g56-u15.g.5.task":"Исправь неверное por на нужное слово","es-g56-u15.g.6":"Я купил это за 5 евро.","es-g56-u15.g.6.task":"Исправь неверное para на нужное слово","es-g56-u15.g.7":"Я еду, чтобы увидеть двоюродных братьев.","es-g56-u15.g.7.task":"Исправь неверное por на нужное слово","es-g56-u16.title":"Сначала, потом, наконец: рассказываем по порядку","es-g56-u16.tip":"Перескажи любимую историю в трёх предложениях с primero, luego, finalmente.","es-g56-u16.w.0":"сначала","es-g56-u16.w.1":"потом","es-g56-u16.w.2":"после (затем)","es-g56-u16.w.3":"наконец","es-g56-u16.w.4":"пока (в то время как)","es-g56-u16.w.5":"вдруг","es-g56-u16.w.6":"лиса","es-g56-u16.w.7":"ворона","es-g56-u16.w.8":"сыр","es-g56-u16.w.9":"ветка","es-g56-u16.w.10":"клюв","es-g56-u16.w.11":"мораль","es-g56-u16.s.0":"Сначала ворона нашла кусочек сыра.","es-g56-u16.s.1":"Потом она села на высокую ветку.","es-g56-u16.s.2":"Вдруг пришла лиса.","es-g56-u16.s.3":"Пока говорила, лиса смотрела на сыр.","es-g56-u16.s.4":"Ворона раскрыла клюв, чтобы запеть.","es-g56-u16.s.5":"Сыр упал на землю.","es-g56-u16.s.6":"Наконец лиса съела сыр.","es-g56-u16.s.7":"Мораль: не верь всем красивым словам.","es-g56-u16.g.title":"Слова-связки в рассказе: primero, luego, después, finalmente, mientras, de repente","es-g56-u16.g.x.0":"Чтобы показать порядок: primero (сначала) → luego/después (потом) → finalmente (наконец).","es-g56-u16.g.x.1":"mientras — «пока, в то время как», de repente — «вдруг». Они делают рассказ живым.","es-g56-u16.g.x.2":"Связки обычно стоят в начале предложения, а после них — запятая: Primero, … Luego, … Finalmente, ….","es-g56-u16.g.0":"Сначала я встаю рано.","es-g56-u16.g.1":"Потом я завтракаю с семьёй.","es-g56-u16.g.2":"Наконец я выхожу в школу.","es-g56-u16.g.3":"Я пою, пока принимаю душ.","es-g56-u16.g.4":"Вдруг пошёл дождь.","es-g56-u16.g.5":"После ужина я читаю сказку.","es-g56-u16.g.5.task":'Перепиши с "después de" (после)',"es-g56-u16.g.6":"Сначала лиса увидела сыр.","es-g56-u16.g.6.task":'Добавь в начало "Primero,"',"es-g56-u16.g.7":"Наконец ворона потеряла сыр.","es-g56-u16.g.7.task":'Добавь в начало "Finalmente,"',"es-g56-u16.r.ko":"Лиса и ворона","es-g56-u16.r.genre":"Басня","es-g56-u16.r.p.0":"Однажды утром ворона нашла на окне какого-то дома кусочек сыра. Она схватила его клювом и улетела на самую высокую ветку дерева. Ей было очень хорошо, и она собиралась съесть сыр не спеша.","es-g56-u16.r.p.1":"Вдруг мимо пробегала лиса и увидела сыр. «Здравствуйте, госпожа Ворона, — сказала лиса. — Какие у вас прекрасные перья! Наверняка и голос у вас самый красивый в лесу. Не споёте ли вы для меня?» Пока говорила, лиса не сводила глаз с сыра.","es-g56-u16.r.p.2":"Польщённая ворона раскрыла клюв, чтобы запеть… и сыр упал на землю. Наконец лиса подхватила сыр и убежала. Мораль: не верь всем приятным словам.","es-g56-u16.r.q.4.o.0":"польщённая (гордая)","es-g56-u16.r.q.4.o.1":"голодная","es-g56-u16.r.q.4.o.2":"грустная","es-g56-u16.r.q.4.o.3":"сонная"},a={...s,...e,...g,...u,...t};export{a as default};
